INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'beginner_guide_frequently_asked_questions',
  'Beginner-guide',
  'Frequently Asked Questions',
  'Простые вопросы, советы для начала игры, основы игры
### Золотые объявления
- Получайте золотые объявления 7 раз в день с 10-минутным перерывом между каждым объявлением
 - Если вы пропустили объявление, просто подождите 10 минут до следующего.
### Потратить золото
- Используйте калькулятор распределения статистики в Master Optimizer ( <#1092343850019868682> ) для эффективного принятия решений о расходах.
### Онлайн против автономной фермы
- Онлайн-ферма лучше, предоставляя больше ресурсов, кроме дайса. [[beginner_guide_frequently_asked_questions]]
### Рекомендуемая сцена для фермы
- Для новых игроков занимайтесь фермой везде, где ваш Фульгуроус может один раз убить.
- Если вы прошли сцену 160, обратитесь к калькулятору фермы сцены в Master Optimizer ( <#1092343850019868682> ) для оптимальной фермы.
### Монстры за волну (MPW)
- 4 MPW лучше всего для фермы золота и опыта.
- 18 MPW лучше для фермы всех остальных ресурсов.
- Детали сцены доступны в игре после сцены 160 или в <#1092343850019868682> 
### Увеличение восстановления маны
- Повысьте уровень пассивного навыка Mana Dope спутника Луны.
- Для новых игроков наличие 1-2 строк промо/страницы спутника с восстановлением маны также может помочь.
### Белые перья
- Используйте 3x в тренировочной пещере каждый день, 
- Сохраните остальное для [[adventure_closed_mine|закрытых шахт]] во время событий с доступным бафом золота. Идеально вы будете использовать 250-300 белых перьев в течение одного дня с горячим временем, поэтому убедитесь, что у вас достаточно перьев для максимизации прибыли ресурсов в течение 2-часового периода
### Ферма закрытых шахт
- Занимайтесь фермой на 2-й сцене самого высокого уровня, который вы можете пройти.
- Если вы не можете победить 90-95% этой сцены, уменьшите уровень или сцену, пока не сможете
- Не занимайтесь фермой на 5-й сцене (там меньше мобов из-за босса, поэтому меньше возможностей для дропов)
### Вход в подземелье - что произойдёт, если я выйду?
- Вы повторите подземелье после выхода из Мерной щели, Убежища спящего пламени, Леса циркуляции, Долины драконов и Дневника тренировки.
- Нет повторного входа при выходе из тренировочной пещеры и закрытых шахт, поэтому рекомендуется завершить их, даже если это пойдёт плохо.
### Преимущества элементов
- Спутники, закрытые шахты, тренировочная пещера и щель имеют элементы - это означает, что вступают в силу преимущества/недостатки элементов. Смотрите подсказку в игре.
- Боссы сцены не имеют элемента, и все навыки имеют множитель 1x против них.
### Эффекты оружия душ
- Эффекты оружия душ не складываются; активно только оснащённое оружие.
- Вы можете разобрать старые оружия.
### Ферма душ / фрагментов оружия душ
- Фрагменты оружия душ - это случайные дропы со всех мобов.
- Занимайтесь фермой на сцен 18 MPW, так как там больше мобов для убийства.
### Эффекты костюма
- Эффекты костюма складываются. Это включает все полученные эффекты, поэтому разблокируйте их все.
### **Горячее время**
- Горячее время - это бафф, доступный в выходные дни, получаемый из почтового ящика ~10 минут после сброса.
- Он дарует 2x золота и опыта за 2 часа.
- Бафф складывается с буфами прокрутки золота/опыта и буфами события золота/опыта.
- Горячее время продолжается в автономном режиме (в отличие от других буфов). Обязательно держите игру открытой на полные 2 часа, чтобы максимизировать преимущества горячего времени!
### Бафф события
- Рекомендуется использовать бафф Куба в будни, бафф золота в выходные, бафф золота во время закрытых шахт + горячее время

## Эффективное использование буфов (прокрутки, бафф события, горячее время)
- Во время активных событий можно использовать только один бафф события в день. Выберите наиболее подходящий для вашего аккаунта (например, рекомендуется бафф куба).

1) **Фокус на опыте**:
 - Используйте прокрутку опыта + горячее время.
 - Завершите пробеги тренировочной пещеры.
 - При необходимости используйте бафф события об опыте на этом этапе.

2) **Фокус золота**:
 - Используйте золотую прокрутку.
 - При необходимости используйте бафф события золота на этом этапе.

3) **Занимайтесь фермой в течение 2 часов на сцене с мощностью 4MPW.**

4) **Фокус куба:**
 - Используйте прокрутку куба.
 - Участвуйте в действиях щели.
 - При необходимости используйте бафф события куба на этом этапе (рекомендуется).

5) **Фокус на экипировке:**
 - Используйте прокрутку оборудования.

6) **Занимайтесь фермой в течение 2 часов на сцене с мощностью 18MPW.**

7) **Получайте прибыль и забирайте награды!**
### Информация по тратам/пакам/пассам в разделе 8
https://namu.wiki/w/%EC%8A%AC%EB%A0%88%EC%9D%B4%EC%96%B4%20%ED%82%A4%EC%9A%B0%EA%B8%B0
