## Основные термины геймплея
* MPW = монстров на волну (Monsters Per Wave) - [[beginner_guide_glossary_of_terms]]
* GK = прокачка знаний (Growing Knowledge) - [[beginner_guide_glossary_of_terms]]
* SH = SuperHuman (суперчеловек) - [[beginner_guide_glossary_of_terms]]
* TD = дневник тренировки (Training Diary) - [[beginner_guide_glossary_of_terms]]
* TC = тренировочная пещера (Training Cave) - [[beginner_guide_glossary_of_terms]]
* CM = закрытые шахты (Closed Mines) - [[beginner_guide_glossary_of_terms]]
* FoC = лес циркуляции (Forest of Circulation) - [[beginner_guide_glossary_of_terms]]
* BLORB = черная сфера (Black Orb) - [[beginner_guide_glossary_of_terms]]
* SW = Soul Weapon (душевное оружие) - [[beginner_guide_glossary_of_terms]] [[beginner_guide_glossary_of_terms]]
* SP = мастерство навыков (Skill Proficiency) - [[beginner_guide_glossary_of_terms]]
* SM = Skill Mastery (система мастерства навыков) - [[beginner_guide_glossary_of_terms]]
* Fams = фамильяры (Familiars) - [[beginner_guide_glossary_of_terms]]
* BT = прорыв (Breakthrough) - [[character_memory_tree|Древо памяти]]


# <#1205031896900309052> Пробуждения и навыки

## Пробуждение
* A0 – A18 = Уровни пробуждения духа  
  * Начинается с A0 (Легендарный)  
  * Переходит в A6 (Мифический)  
  * Затем переходит в A12 (Бессмертный)
  * Заканчивается на A18 (Древний)  

## Навыки
* E1 – E5 = Уровень навыка духа  
  * Все легендарные духи начинаются с E1
#  <#1124553633883754637> и <#1121538334523654154> система

## Классы персонажа
* C1 – C20 = Ранг класса персонажа  
   * C20 = Взрыв <:class20:1055586744231272498> 
   * C20 6* = Тера <:tera:1055588078254825585> 
   * C20 12* = Семя <:Seed:1174921381201330276> 
   * C20 18* = Новая звезда <:Nova:1276144888508977162>

## Формат снаряжения
* [Редкость][Ранг][Тип]  
  * **Редкость:**  
    * M = Мифическое  
    * L = Легендарное  
    * E = Эпическое  
    * R = Редкое  
    * G = Хорошее  
    * C = Обычное  
  * **Ранги:** 1 по 4  
  * **Типы:** `Wep` = Оружие, `Acc` = Аксессуар  

* Пример:
  * `M1 Acc` = Мифическое снаряжение ранга 1
  * `L3 Wep` = Легендарное оружие ранга 3

> **Примечание.** Снаряжение Бессмертия обычно называют по имени, например: `Orr` (Оружие Бессмертия), `Orb` (Аксессуар Бессмертия).

# Популярные сокращения <#1125052747952160888>
Из-за большого количества навыков в игре перечислены только 10 наиболее часто упоминаемых навыков:

* FS = Flame Slash (Пламенный удар)  
* HFS = Hellfire Slash (Адский огненный удар)  
* DH = Demon Hunt (Охота на демона)  
* RL = Red Lightning (Красная молния)  
* WoG = Wrath of Gods (Гнев богов)  
* WB = Warrior Burn (Пламя воина)  
* LB = Lightning Body (Тело молнии)  
* SC = Strong Current (Сильное течение)  
* EW = Earth''s Will (Воля земли)  
* DW = Dancing Waves (Танцующие волны)  

> **Примечание.** Игроки часто добавляют к навыкам префикс «e» или «a», чтобы указать, что навык был пробужден посредством мастерства навыков (разблокируется через Эфир).
> Второе пробуждение обозначается как «e2» или «a2», обычно открывается в эндшпиле.
> **Примеры:** `eFS / aFS` = Пробужденный пламенный удар, `a2FS` = Пробужденный 2 пламенный удар
# Дополнительные примечания

> **Приют спящего пламени**: нет стандартизированной аббревиатуры — варьируется в зависимости от пользователя.

