INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'beginner_guide_online_vs_offline_farming',
  'Beginner-guide',
  'Online VS Offline Farming',
  'Сравнение онлайн- и оффлайн-фармаж

### Онлайн против оффлайн
* Онлайн-фармаж лучше, чем оффлайн!
1 - У вас есть ограниченное количество часов, в течение которых вы можете играть оффлайн (10 часов), поэтому если вы забудете войти в систему и получить свои награды, вы перестанете получать награды.
2 - Вы не получите алмазы за ежедневные квесты.
3 - Вы не получаете оборудование с оффлайн-фермы.
4 - Скорость получения кубиков и душ с оффлайн-фермы намного ниже, чем с онлайн-фермы (вы можете проверить в калькуляторе этапов и увидеть разницу).

* Для новых игроков всё ещё есть некоторые преимущества оффлайн-фермы:
> * До 160-го этапа вы всё равно не сможете выбирать между 4mpw и 18mpw.
> * Вы получаете больше кубиков с оффлайн-фермы, что помогает повысить умения «Повышение слэйера» и «Повышение компаньона» до мифического ранга.
> * Вы получаете больше опыта с оффлайн-фермы, но этот эффект значительно снижается, когда все слоты навыков разблокированы.
