  'https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/Beginner-guide/path_of_suggested_progression/eventspending_guide_updated.png
# Гайд по прогрессии для новичков в Slayer Legend

> **Примечание:** Гайд рассчитан на старт с нуля и показывает, когда и как прогрессировать максимально эффективно, не сливая ключевые ресурсы. Если вы уже не на старте, все равно можно идти по пунктам сверху вниз и закрывать пропущенные этапы.

## 1. День 1-5: Slayer Newbie Pass
* На 5-й день вы получите бесплатный <:M1:1211868018590879864>
* Призывайте аксессуары, чтобы открыть Meditation.
> Примечание: карту <:Meditation:1054837527204352010> вы получите на 100 уровне персонажа.
* Если покупаете пасс:
* Получите <:mythic1:1055585728140148747>
* Если F2P:
* Призывайте ради <:mythic1:1055585728140148747>
* Также подумайте о покупке **Ad-Free Pack** для более эффективного фарма.
* Ежедневно забирайте награды [[shop_shop|Shop]].
* Проходите все доступные Appearance battles.

## [[character_training_diary|Skills]], которые нужно приоритизировать
Никогда не объединяйте Mythic-снаряжение слишком рано. Открывайте в таком порядке:
* <:Supersonic:1054837538793197628> , <:PillarofFire:1054837539896295484> , <:Blizzard:1054837537312608287> , <:OrrBase:1055585922177040454>, <:rave:1055598059628789772>, <:DemonHunt:1054837525799248034>
* Большая часть экипировки придет из [[stage_stage_farm_info|фарма]]

## 2. Стадии 100-120: открытие ключевых систем
* Откройте Spirits и Class.
* Получите **минимум 3 Epic или Legendary** духа.
* Избегайте <:Leg_bo:1060758772752056380><:Leg_ark:1060758770373886002><:Leg_herh:1060758774421409792>
* Начинайте призыв [[equipment_relics|Relics]].
* Цель: STR/CRIT = 30.

## 3. [[character_class|Class]] и [[adventure_adventure|Spirits]]
### Класс (Class)
* Призывайте, пока не получите **минимум C17**.

### Духи (Spirits)
* [[spirit_spirits|По одному на каждый элемент]]
<:Leg_sala:1060758775839080598> - Awaken 6 раз (Mythic / [A6](https://discord.com/channels/1052865879609724968/1374493056430248026/1374493056430248026))
<:Leg_zappy:1060758779488112701> - A6
<:Leg_todd:1060758778221436989> - Enhanced 5 раз (E5)
<:Leg_loar:1060758780775764058> - E5 -> A2+
Босс: <:Leg_loar:1060758780775764058><:Leg_zappy:1060758779488112701><:Leg_sala:1060758775839080598>
Фарм: <:Leg_todd:1060758778221436989><:Leg_zappy:1060758779488112701><:Leg_sala:1060758775839080598>

## 4. Вехи midgame
## [[equipment_weapons|Weapon]] и [[equipment_accessories|Accessory]] теперь улучшаются дальше
### [[stage_stage_farm_info|Фарм]] аксессуаров 18 MPW
Начинайте фарм сразу после победы над <:adamant:1054852905020170390>, пока не откроете:
* <:StrongCurrent:1054837556778373120>, <:WrathOfGods:1054837540970057778>, <:orb:1127994010422739075>, **<:Mantra:1054837329367420998> Lv1**, <:LightningBody:1054837662445469706>
* Если не хватает карточек навыка для <:StrongCurrent:1054837556778373120> или <:WrathOfGods:1054837540970057778>, используйте Mythic Skill Selector (доступен в некоторых ивентах) или призывайте Skills до 1 карточки.

# Не открывайте <:WarriorBurn:1054837661195583558>

## Мастерство навыков (Skill Mastery)
* Откроется после победы над <:ether:1060039749336830002>.
* Как можно раньше Awaken для <:FlameSlash:1054837335084236881> и <:HellfireSlash:1054837443347615796> под boss/promo сборки.
* Периодически прокачивайте по мере набора очков, останавливаясь на узле <:PillarofFire:1054837539896295484> на странице 3, так как он стоит <:mythic1:1055585728140148747>.

## [[equipment_soul_weapon_engraving|Гравировка Soul Weapon]]
* Открывается после крафта Pride или выше.
* Держите смешанный набор Gold/Atk/Crit для фарма и боссов: золото отсюда очень полезно в early-midgame. Позже, когда ценность золота упадет, можно отказаться от Gold.

## Орр (Orr)
Если на Pity 7 гарантирован крафт <:OrrBase:1055585922177040454>, призывайте до получения Orr. Иначе продолжайте фармить на Orr (помните, что бесплатный M1 дается за Skill Mastery).
* Нужно 5x <:mythic1:1055585728140148747> = <:OrrBase:1055585922177040454>

## Открытие Rave
* 1x <:mythic1:1055585728140148747> = <:rave:1055598059628789772>
* При необходимости спрашивайте, как правильно использовать [[beginner_guide_rage_rave_early_late_game_rotation_late|Rage + Rave]].

## 4.5. Опциональные апгрейды, если трудно пройти <:blackmythril:1060039750913888296>
* Поднимите Str/Crit/Spd Relics до 40-50 или Class до <:class19:1055586742952018001>.

## 5. Цели апгрейда
* (После <:blackmythril:1060039750913888296>) Призывайте аксессуары до pity 7, чтобы получить <:orb:1127994010422739075> и [[equipment_black_orb|Black Orb]] <:BlackOrb:1209708648952107028>
* Ваш основной элемент - Fire.
* Не игнорируйте Wind: это главный элемент фарма.
* Черные перья сохраняйте на late game.
* Переключайтесь с фарма аксессуаров на Weapon после получения <:Mantra:1054837329367420998> Lv1, если у вас еще нет <:Blizzard:1054837537312608287>.
* (Опционально) Если <:Blizzard:1054837537312608287> уже есть, получите <:LightningBody:1054837662445469706> до перехода на фарм оружия.
* Полностью пробудите 4 духа до [[equipment_accessories|Mythic]].
* Призывайте реликвии, пока STR/CRIT не станет 100.

## 5.5. Опциональные апгрейды до полного ухода в grind класса (можно и после c20 4*)
* Mythic E5: <:Leg_mum:1060758787092402237> <:Leg_noah:1060758788237443132> <:Leg_zappy:1060758779488112701> (через ивенты или призыв)
* [[mid_game_promotions_dark_nox|Фамильяры]]: призыв до 35-38*
* В идеале <:Fam_HI:1319159002948440084> <:Fam_KU:1319159008204165131> <:Fam_NA:1319158997508423793> по 5-6* каждый.

## 6. Class Part 2 и [[character_memory_tree|Memory Tree]]
* Призывайте class до <:Seed:1464096337959063674>.
* Путь от c17/c19 до c20 12* может быть долгим и утомительным, но это самый оптимальный маршрут. По дороге вы также пройдете несколько Promotion.
* Улучшайте Memory Tree сразу после открытия seed.

## 6.5. [[companion_beast|Звери]]
* Во время гринда класса вы победите <:warfrost:1060039928794333184> и откроете зверей.
Получите всех 20 зверей, используя snacks и monthly whistles.
После стартовых 21/21 зверей приоритет - <:Seed:1464096337959063674>.
Используйте snacks и monthly whistles до 750 tokens, затем можно перейти на snacks + минимум whistles.
Сохраняйте все tokens, пока не закончите финальных gold/unique зверей до A6.

## 7. Прогресс Orr, Orb и Nova
### Прогресс Orr:
* 4x <:mythic1:1055585728140148747> = <:DemonHunt:1054837525799248034>
* 9x <:mythic1:1055585728140148747> = <:OrrBase:1055585922177040454> -> <:Orr6:1055585923364048966>
* 9x <:mythic1:1055585728140148747> = <:Orr6:1055585923364048966> -> Orr12
* 9x <:mythic1:1055585728140148747> = Orr12 -> Orr18
* Тратьте алмазы на призыв только до Pity 8, дальше используйте рекламу; основную часть m1 вы получите фармом.

### Прогресс Orb:
Если у вас <:BlackOrb:1209708648952107028> уровня 20-24, можно временно перейти на фарм/призыв аксессуаров, чтобы быстро получить <:orb6:1378271019399385209>, а потом вернуться к фарму оружия.

После Seed вам нужен Orb 6 для усиления <:BlackOrb:1209708648952107028>, а Dark Fragments пойдут на улучшение Ring of Courage.
* 4x <:M1:1211868018590879864> = <:WarriorBurn:1054837661195583558>
* 9x <:M1:1211868018590879864> = <:orb:1127994010422739075> -> <:orb6:1378271019399385209>

### [[mid_game_promotions_dark_nox|Фамильяры]]
* 41/44/47* в зависимости от того, сколько soul marbles вы можете генерировать.
* <:Fam_HI:1319159002948440084> <:Fam_KU:1319159008204165131> <:Fam_NA:1319158997508423793> <:Fam_PE:1319159006841012306> <:Fam_MUS:1319159228266578000>

### Финальные цели:
* <:orb6:1378271019399385209>
* <:Seed:1464096337959063674> до 5*
* Immortal Spirits минимум 3-6
* <:Leg_noah:1060758788237443132> <:Leg_mum:1060758787092402237> <:Leg_zappy:1060758779488112701> -> <:Leg_loar:1060758780775764058> -> <:Leg_sala:1060758775839080598> -> <:Leg_luga:1060758784106057880> -> <:Leg_kart:1060759190672515092> / <:Leg_todd:1060758778221436989>
* <:light_shard:1400147911526056067> для <:Nova:1276144888508977162> -> Ancient Spirits -> Constellations -> [orr24](https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/Beginner-guide/tldr_version_of_path_for_promo/1349197221496885309.webp)

## 8. Эндгейм-цикл
* После <:Nova:1276144888508977162> можно переходить к [[character_constellation|constellations]].
* Крафтите Small и Medium для максимальной эффективности по времени/ценности; Large слишком ресурсозатратны, обычно рекомендуют остановку на lv12 0/20.
* После [orr24](https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/Beginner-guide/tldr_version_of_path_for_promo/1349197221496885309.webp) можно открыть <:PillarofFire:1054837539896295484> в Skill Mastery.
* Если у вас 9/10* <:Fam_TI:1319158999249064007> и/или aDH на 5-й странице SM, в этот момент можно использовать черные перья для роста Earth dmg%.
* Призывайте Ancient Spirits.
* Повышайте familiars до 50*+.
* Сохраняйте алмазы для будущих обновлений, если текущие апгрейды слишком дорогие.
* Используйте <:mythic1:1055585728140148747> для апгрейдов <:rave:1055598059628789772> после <:Nova:1276144888508977162> + [orr24](https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/Beginner-guide/tldr_version_of_path_for_promo/1349197221496885309.webp).
* Вернитесь к фарму аксессуаров, когда оружие завершено.
* Зеленые перья можно использовать в любое время для буста, но лучше после закрытия основных алмазных апгрейдов, чтобы максимизировать ценность.

https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/Beginner-guide/tldr_version_of_path_for_promo/1349197221496885309.webp

* Приоритет, куда тратить <:mythic1:1055585728140148747> и <:M1:1211868018590879864>:
* <:mythic1:1055585728140148747>: <:Supersonic:1054837538793197628> -> <:Blizzard:1054837537312608287> -> <:OrrBase:1055585922177040454> -> <:rave:1055598059628789772> Lv1 -> <:DemonHunt:1054837525799248034> -> Orr23 -> <:light_shard:1400147911526056067> -> Ancient Spirits -> Constellations -> orr24 -> Skill Mastery -> <:rave:1055598059628789772> Lv5
* <:M1:1211868018590879864>: <:StrongCurrent:1054837556778373120> -> <:WrathOfGods:1054837540970057778> -> <:orb:1127994010422739075> -> <:Mantra:1054837329367420998> Lv1 -> <:LightningBody:1054837662445469706> -> <:Mantra:1054837329367420998> Lv5 -> <:WarriorBurn:1054837661195583558> -> <:orb6:1378271019399385209> -> <:Nova:1276144888508977162> -> <:light_shard:1400147911526056067> -> Ancient Spirits -> Constellations -> Skill Mastery -> <:orb24:1378271179365814425>
* Для подробностей также смотрите Slayerpedia.
