INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'beginner_guide_where_to_spend_diamonds_emeralds_and_feathers',
  'Beginner-guide',
  'Where to spend Diamonds, Emeralds and Feathers',
  '1. **Руководство по алмазам**
Пожалуйста, следуйте <#1266503499009753110>.
Или вариант 2: откройте <#1234061449824047174> или <#1052865880016568407>, проверьте закреплённое сообщение📌 и следуйте инструкциям.

2. **Руководство по изумрудам**

**На что я трачу изумруды?**
Большая часть ваших изумрудов будет потрачена на повышение уровня навыков компаньонов.

**Должен ли я разблокировать слоты навыков за изумруды?**
Нет, разве что если вы готовы платить немало денег.

**Должен ли я разблокировать третий слот духа за изумруды?**
Да! Это дёшево и стоит того, чтобы разблокировать на 200 уровне.

**Как я получаю изумруды?**
Истории, приключения, прогресс компаньонов, ежедневная торговля кубиками и камнями. Не торгуйте перьями и алмазами. Откройте магазин, перейдите в раздел товаров и прокрутите вниз.

3. **Руководство по перьям**
Тратьте перья только в тренировочной пещере для получения опыта/класса. Однако, если идёт событие и это выходные дни, вы можете потратить перья в закрытых шахтах.
Мудро распределяйте свои перья между усилениями события, Hot Time и усилениями золота в закрытых шахтах. Эта стратегия максимизирует ваши доходы и награды.
> Примечание о перьях: до получения Orr (а точнее, до продвижения по Ether) доход от золота будет намного ниже. Так что даже после завершения приключения и накопления перьев может быть полезно подождать, пока ваш доход золота не возрастёт, прежде чем использовать перья в закрытых шахтах. Лучше всего иметь 250-300+ перьев на двухчасовый сеанс в шахтах.
