**• Эндгейм**
<:Fulgurous:1054837528714293288> <:Blizzard:1054837537312608287> <:PillarofFire:1054837539896295484> <:DemonHunt:1054837525799248034> <:Meditation:1054837527204352010>
<:SpeedSword:1054837558133129236> <:EarthsWill:1054837582124560485> <:CurvedBlade:1054837628563890197> <:BurningSword:1054837580388126721> <:FireSword:1054837553951416431>
<:noah:1060758788237443132> **Духи**
В основном используется в битвах, ориентированных на мобов; <:mum:1060758787092402237> <:zappy:1060758779488112701> <:kart:1060759190672515092>, любой дух, увеличивающий ваш урон мобам.
В основном используется в битвах, ориентированных на боссов; <:noah:1060758788237443132> <:loar:1060758780775764058> <:sala:1060758775839080598>, любой дух, увеличивающий ваш урон по боссам.

<:guide:1055587557976580106> **Советы**
Использование Life Mana рекомендуется для обеспечения устойчивости, а также для решения любых проблем с маной, которые могут у вас возникнуть. Вы также можете просто вставить восстановление маны в дополнительную способность компаньона.

**Информация**
**Приключения**
1. Лучшее место для сжигания перьев; за алмазы/изумруды чистые награды
2. Обратите внимание на атрибуты каждой локации; это повлияет на ваш урон
3. Должна быть возможность очистить Adventure до <:ether:1060039749336830002>.
