<:LightningBody:1054837662445469706> <:Rage:1054837629679575160> <:BurningSword:1054837580388126721> <:FireSword:1054837553951416431> <:Fulgurous:1054837528714293288>

### <:MelonLord:1134338853679923230> Духи
Предпочтительно использовать Todd <:Leg_todd:1060758778221436989>, Mum <:Leg_mum:1060758787092402237> и Zappy <:Leg_zappy:1060758779488112701>. По ситуации также можно брать Radon <:Leg_radon:1060758791207002131>, Kart <:Leg_kart:1060759190672515092>, Luga <:Leg_luga:1060758784106057880> или вашего самого прокачанного пробужденного духа.

## 🤓 Дополнительная информация
- В целом: чем выше этаж, тем больше ресурсов.
- Золото и опыт заметно растут в зоне 1 каждого 4-го этажа по схеме 4n+1 (этажи 1, 5, 9, 13...).
- Опыт особенно растет в зонах 1 и 2 на этих этажах.
- Кубы растут каждые 2 этажа по схеме 2n+1 (1, 3, 5, 7...). После 250-го этажа прирост кубов становится почти незаметным.
- На каждом этапе 350 врагов (10 волн по 35). В зоне 5 последних две волны заменяются боссом.
- Элемент этажа при каждом заходе определяется случайно.

## <:guide:1055587557976580106> Советы
- Проталкивайтесь на максимальный этаж, проходя максимально возможную для вас зону 5 с 1 пером.
- Для фарма используйте 3 пера и повторяйте зоны 1-4 на этаже, где вы убиваете 90-95% врагов при земляном элементе этажа (обычно это самый сложный элемент для зачистки, так как основные фарм-навыки ветровые).
- Лучше фармить зону 2, но подойдет любая зона кроме 5. В зоне 5 меньше мобов, значит и ресурсов меньше. В зоне 1 опыта немного меньше, чем в зоне 2.
- Старайтесь фармить нечетные этажи с усиленными наградами (см. схему выше). После 250-го этажа делайте упор на этажи 4n+1, так как буст кубов уже почти не влияет.
- Тестируйте под свой аккаунт: профиль урона меняется, и лучший этаж/зона могут отличаться. Эти рекомендации - базовый ориентир.
- Лучшее время для «Закрытой шахты» - когда можно сложить ежедневные свитки + weekend hot time + ивентовый бафф для 12x золота и 6x опыта.
- Ивентовый бафф ради дополнительных кубов в «Закрытой шахте» обычно неэффективен: основная часть кубов идет из сундуков. Обычный ежедневный свиток кубов все еще полезен, так как с мобов в «Закрытой шахте» кубов обычно больше, чем на обычном фарме 18mpw.
