VALUES (
  'adventure_dragon_valley',
  'adventure',
  'Dragon Valley',
  'Информация о Dragon Valley

# Долина драконов (Dragon Valley) (СЕЗОН 3 ЗАКАНЧИВАЕТСЯ: **18 МАЯ 2026**)
------------------------------------------------------
## Требования для открытия
- В гильдии должно быть не менее 8 участников.
- Уровень гильдии должен быть не ниже 10.

------------------------------------------------------
## Фазы и расписание (по времени серверного ресета)
- **Понедельник** -> Матчмейкинг
- **Вторник - четверг** -> Исследование
- **Пятница - воскресенье** -> Рейд

------------------------------------------------------
## **Матчмейкинг**
- Каждая гильдия делит участников на 4 региона с разными элементами (в полной гильдии из 20 человек - по 5 на регион).
- Система автоматически собирает 5 гильдий (обычно близкого уровня с небольшой разницей) и помещает их в одну лигу.
- Всего **4 тира**: Beginner, Veteran, Expert, Elite.

------------------------------------------------------
## Ранги
- Каждую неделю гильдии получают Ranking Points (RP), которые повышают тир и общий соревновательный уровень.
- Чем выше тир, тем выше награды.
- Количество RP зависит от итогового места в лиге, процента от общего очкового вклада вашей гильдии и ряда небольших неизвестных факторов.
- Индивидуальный ранг внутри гильдии не дает отдельной выгоды.
- В конце сезона ранги полностью сбрасываются.

------------------------------------------------------
## **Фаза исследования**
- Цель: набирать очки через готовку и поиск следов виверны.
- Расположение виверны и следов одинаково для всех участников лиги.
- После фазы исследования каждый участник получает очки в зависимости от места гильдии в регионе.

### Спавн мобов
> Названия зон отличаются по элементальным регионам.
- **Meat (мясо):** 100 мобов
- **Honey Fruit (медовый фрукт):** 50 мобов
- **Moss/Root (мох/корень):** 200 мобов
- **Potato (картофель):** 20 мобов

### Преимущества исследования
> 3 захода в день.
- **Разные материалы** в зависимости от выбранной зоны.
- **Рейтинговые очки** для таблицы лидеров.
- Заполнение **шкалы прогресса исследования**.

### Поиск виверны
- По мере заполнения шкалы исследования растет шанс **найти след виверны**.
- Игрок, который нашел след, получает бонус 10000 очков.
- В регионе с виверной доступно 3 следа.
- В регионах без виверны доступен 1 след.

### Примечания для сезона 2
- Очки можно получать, сжигая ветки. Часто выгоднее покупать сухие ветки у Wandering Merchant: они дают 1200 очков против 1000 у готового блюда.
- Пока горит костер, таймер исследования увеличивается. Поэтому первое исследование в первый день обычно короче, но если оставить ветки на следующие дни, это можно компенсировать.
- Перед завершением фазы исследования сожгите все оставшиеся ветки ради дополнительных очков (100 очков за 10 веток).

--------------------------------------------------------------
## **Система готовки** [УСТАРЕЛО - СМ. ГАЙД S3 НИЖЕ]
Готовка позволяет создавать **бафф-еду** из материалов, полученных в исследовании. **На бои исследования** готовка не влияет, но дает бонусы **в рейдовой фазе**.

### Порядок приоритета
1. **Bubble Hotpot** - **максить в первую очередь** (увеличивает получение материалов в исследовании до 25%).

### Командный фокус
> В S2 приоритет сухих веток у Wandering Merchant часто дает больше очков, чем готовка.
- **Skewer** - увеличивает длительность баффов. (Примечание для S2: заменен на **Crispy Pork Cutlet** - повышает урон, пока виверна готовит мощную атаку)
- **Omurice** - увеличивает время боя в рейде. (Примечание для S2: заменен на **Warm Stew** - повышает сопротивление холоду и снижает длительность заморозки навыков)
- **Fruit Salad/Chewy Pasta** - снижает перезарядку навыков (CDR).
- **Immortal Steak** - повышает урон по вивернам.
- **Elemental Bonuses (элементальные бонусы)** - прокачивайте элементальный урон, который реально используете (обычно огонь и земля). (Примечание для S2: баффы Wandering Merchant для этого обычно малоэффективны)

Командная координация очень важна. Не вкладывайтесь только в одно блюдо - распределяйте улучшения, чтобы получить сбалансированные бонусы.

--------------------------------------------------------------
## **Фаза рейда**
- Вся гильдия сражается с **виверной**, чтобы набрать больше очков.
- У каждой виверны уникальные **навыки и паттерны атак** в зависимости от **элемента**. Одна и та же атака подряд не повторяется.
- **Навыки снижения HP и некоторые способности духов (например, Radon, Loar, Sala) не работают.**

### **Элементальные способности виверны** *(W.I.P.)*
- **Fire Wyvern**: сжигает и временно удаляет несколько навыков.
- **Earth Wyvern**: блокирует навыки песком и перемешивает их.
- **Water Wyvern**: замораживает навыки, останавливает откаты и не дает использовать скиллы.
- **Wind Wyvern**: замораживает навыки эффектом торнадо, но откаты продолжают идти.

### **Боевая механика**
- **Stun и Freeze** только **приостанавливают** виверну, но **не отменяют** ее атаку.
- **Dancing Wave** позволяет уклоняться от урона, но **не** защищает от специальных эффектов (удаление навыков, стан и т.д.).
- **Wyvern Ultimate (ультимейт виверны)**:
- Дважды за бой виверна начинает зарядку атаки, и появляется ваш питомец гильдии.
- Если успеть нанести достаточно урона (желтая шкала) до завершения зарядки (синяя шкала), питомец нанесет **огромный** урон виверне.
- Тайминги и длительность ульты зависят от элемента виверны.
- Лучше всего записывать урон питомца в Rave.
- Wyvern Ultimate 1: при провале виверна улетает и наносит сильную атаку игроку.
- Wyvern Ultimate 2: при провале виверна хватает игрока и вбивает его в землю, теряя последние секунды боя (особенно критично во время Noah).
- **Team Damage Buff (командный бонус урона)**: по мере подключения согильдийцев урон растет на 15% за каждого, максимум до 60%.

-----------------------------------------------------------------
## **Сборка**
Питомец гильдии дает основную часть урона в этом режиме.

### Ранняя игра
<:HellfireSlash:1054837443347615796> <:GigaStrike:1054837450415022140> <:RedLightning:1054837517523882115> <:BurningSword:1054837580388126721> <:CurvedBlade:1054837628563890197>
<:Meditation:1054837527204352010> <:SpeedSword:1054837558133129236> <:EarthsWill:1054837582124560485>

### Середина игры
<:rave:1055598059628789772> <:FlameSlash:1054837335084236881> <:HellfireSlash:1054837443347615796> <:BurningSword:1054837580388126721> <:CurvedBlade:1054837628563890197>
<:Meditation:1054837527204352010> <:StrongCurrent:1054837556778373120> <:WrathOfGods:1054837540970057778> <:SpeedSword:1054837558133129236> <:EarthsWill:1054837582124560485>

### Поздняя игра
<:rave:1055598059628789772> <:DemonHunt:1054837525799248034> <:PowerStrike:1054837360354938950> <:BurningSword:1054837580388126721> <:CurvedBlade:1054837628563890197>
<:WrathOfGods:1054837540970057778> <:Meditation:1054837527204352010> <:WarriorBurn:1054837661195583558> <:SpeedSword:1054837558133129236> <:EarthsWill:1054837582124560485>

### Духи
<:Leg_noah:1060758788237443132> <:Leg_herh:1060758774421409792> <:Leg_ark:1060758770373886002> - предпочтительный набор, но подойдут и другие хорошо пробужденные духи.

### <:guide:1055587557976580106> Советы
- **Использование Rave**:
- Вариант 1: сломайте первый щит навыками, затем запишите Rave на втором щите, чтобы сохранить урон фамильяра и питомца гильдии.
- Вариант 2: запишите Rave во время пробития первого щита, сохраните его и выпускайте на фазе последнего щита.
- Из боя можно выйти так же, как в FoC, поэтому спокойно тестируйте разные варианты.
- Эксперименты с <:Rage:1054837629679575160> <:LightningBody:1054837662445469706> <:WarriorBurn:1054837661195583558> легко приводят к смерти.
- Подбирайте атакующие навыки под свои уровни навыков, урон навыков и ваш элементальный урон по виверне.

-----------------------------------------------------------------
# Механика сезона 2: Wandering Merchant (УСТАРЕЛО)

Торговец появляется только в одном регионе за раз и меняет регион каждый день. Покупки доступны только когда он в вашем регионе.
Одновременно продаются только 3 предмета, а список на неделю фиксирован.

## **Предметы гильдии**
**[Portable Cooking Kit]** - дает 2 случайных уровня блюд для **вашего региона (не всей гильдии)**. Очень полезно.
**[Divine Beast Resonance Stone]** - повышает урон питомца гильдии на 2% за уровень.
**[Ice Gloves]** - повышает ваш урон на 50% за каждый замороженный навык в рейде.
**[Golden Nest]** - дает 2-5 яиц при покупке.

## **Личные предметы**
**[Frost Salt]** - улучшает Thunderbolt Burger, уменьшает число ударов, нужных для ветровых навыков.
**[Blue Fire Herb]** - улучшает Hellfire Curry, дает огненным навыкам иммунитет к Freeze.
**[Snowflake Pepper]** - улучшает Water Soup, добавляет урон по замороженным целям.
**[Cool Sauce]** - улучшает Demon Pizza, повышает урон по вивернам, упавшим после провала мощной атаки.

## Ресурсы
**Dry Branches** - поддерживают костер 2 часа. Дают 1200 очков. Очень полезно.
**Fish** - обязательный ингредиент для Warm Stew. Низкий приоритет.
**Resource Conversion (x2) (меняется еженедельно)** - используйте по необходимости.

-----------------------------------------------------------------
# **< WIP >** Механика сезона 3: Archaeologist
- В каждом исследовательском регионе есть случайный археолог с 3 предметами на продажу (1 гильдейский и 2 личных), которые покупаются за ресурсы исследования.

## Оценка (Appraisal)
- Оценивайте камни из исследования, тратя 10 мха.
- Можно получить окаменелости, драгоценные камни или фрагменты камня.
- Фрагменты камня используются для обмена у археолога.

## Окаменелости
- Найденная окаменелость дает 1000 Hero''s Emblems.
- Если окаменелость входит в целевой набор вашего региона, вы получите дополнительную выгоду. Полный набор дает дополнительный эффект завершения.

Обнаружение окаменелости сразу выдает Hero''s Emblems.

Если находка совпадает с целевой окаменелостью археолога, она записывается в Fossil Board.

Заполнение Fossil Board дает дополнительные эффекты в рейде.

У каждого археолога свои цели по окаменелостям и уникальные бонусы за завершение.

## Драгоценные камни и торг
- Если вы нашли драгоценный камень, археолог предложит ресурсы за обмен.
- Если отказаться, есть шанс, что предложение улучшится; если не улучшится, вы получите указанное количество Hero''s Emblems.
- Торговаться можно до 3 раз, в зависимости от настроения археолога.

- Сапфир = 500 Hero''s Emblems.
- Рубин = 1000 Hero''s Emblems.
- Топаз = 1500 Hero''s Emblems.
- Опал = 2000 Hero''s Emblems.

# Приоритет ресурсов S3
1. В первую очередь берите предметы археолога, которые усиливают исследование.
Например: +10% медалей за исследование, больше камней любого типа, больше ресурсов.
2. Готовьте hot pot + dim sum: цель - максимально повысить шанс нахождения следов и в идеале найти все. Это требует координации всей гильдии.
3. Затем берите прочие предметы археолога без исследовательских бонусов. В долгую почти все они полезны, если подстроить под них игру и закрывать больше окаменелостей.
4. Sushi / steak / hotdog: важные рейдовые бонусы, но они стоят яйца (самый дефицитный ресурс из-за обменов у археолога).
5. Элементальные блюда: огонь/земля чаще всего самые ценные, но в целом старайтесь готовить как можно больше через сделки археолога.
6. Если сделка археолога не помогает готовить больше блюд, обычно выгоднее продать ее за очки. Используйте это: в начале исследования чаще торг, ближе к концу чаще отказ от невыгодных сделок.
