  'Guild',
  '# Система гильдии
* Вступить в гильдию можно после Silver Promotion.
* Создать гильдию можно после Gold Promotion.

## Божественный зверь (Divine Beast)
* С Divine Beast можно взаимодействовать до 5 раз в день:
  * 1-е взаимодействие бесплатное
  * Следующие 4 стоят суммарно 1000 Diamonds
  * За каждое взаимодействие вы получаете Affinity Points, Guild Contribution и Guild Shop Coins
* Уровень Divine Beast привязан к уровню вашей гильдии.
  * Когда зверь повышает уровень, вместе с ним растет и гильдия.
* Есть 4 варианта Divine Beast. Итоговый вариант определяется тем, какое действие вы использовали чаще всего до вылупления.
  * Pet = Ветровой волк
  * Clean = Водная змея
  * Play = Огненная птица
  * Sing = Земляной олень

> Таблица наград и изменений на каждом уровне гильдии
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/adventure/guild/image.png
> Варианты Divine Beast
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/adventure/guild/image.png

## [OLD] Мини-игра гильдии
Быстрая стратегическая мини-игра на основе элементального JoKenPo (камень-ножницы-бумага), открывается на 6 уровне гильдии.
Вы выбираете один из доступных элементов, чтобы победить возможные варианты противника.

### Механика мини-игры
* Побеждает сильнейший элемент (стандартная элементальная иерархия).
* Если элементы одинаковые, побеждает тот, кто нажмет быстрее.
* Если ни один элемент не доминирует, нужно нажать в правильный момент.
* **Ежедневные награды:**
  * 300 монет магазина гильдии
  * 200 вклада в гильдию
* **Мини-игра заканчивается, когда:**
  * У вас заканчиваются все сердца
  * Вы побеждаете всех противников

### Дополнительные заметки по мини-игре
* Начиная с 10 раунда появляется таймер на принятие решения.
* Чем дальше вы проходите, тем больше доступных элементов может появляться: до 4 вариантов у вас или у противника.
* Может появиться элемент Light: он работает как wild card и побеждает любой другой элемент.
Благодарность за вклад Ovokano и Leohtberend.

## Гильдейские запросы (Guild Requests)

**Открывается на 9 уровне гильдии**
Собирайте **Corrupted Aura** каждую неделю, чтобы заполнять шкалу наград гильдии.

Каждую неделю гильдия получает **6 уникальных запросов**, и у каждого есть:

- **Эффект благословения (Blessing Effect)**
Случайный положительный эффект, применяющийся к запросу.

- **Эффект порчи (Corruption Effect)**
Случайный отрицательный эффект, связанный с запросом.

- **Элемент (Element)**
Каждый запрос получает случайный элемент на неделю.

- **Прогресс запроса (Request Progress)**
Показывает, сколько членов гильдии отправили запрос.
После заполнения запрос становится недоступным, но приносит гильдии **бонусную Corrupted Aura**.

- **Сложность (Difficulty)**
Масштабируется с вашим уровнем продвижения и влияет на личные награды.
Забрать можно только **одну награду в неделю**.

> После получения награды вы все равно можете нажимать "Investigate" на других запросах и тренировать бой без получения наград.

### Недельная конфигурация запросов (похоже, фиксированная)
- 1 запрос на **4 игроков** -> 5,000 Corrupted Aura
- 4 запроса на **5 игроков** -> 7,500 Corrupted Aura каждый
- 1 запрос на **6 игроков** -> 10,000 Corrupted Aura

### Рекомендуемая координация (лимит 20 участников в гильдии)
- **Вариант A**
Закрыть все **4x запроса на 5 игроков**

- **Вариант B**
1x 4 игрока
1x 6 игроков
2x 5 игроков

https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/adventure/guild/image.png
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/adventure/guild/image.png

## Магазин гильдии
В магазине гильдии доступны:
* Бесплатный ежедневный Guild Support Box
* Различные товары с собственной ценой

### Приоритет покупок
Ранняя/средняя игра:
* Коробка экипировки
* Случайный свиток духа
* Билеты класса

Поздняя игра:
* Билеты навыков
* Алмазная коробка
* Случайный свиток духа

Не рекомендуется:
* Изумрудная коробка

> Список товаров магазина с эффективностью в пересчете на Diamonds
>
> Примечание: из-за лимитов покупок (например, только 5 appearance coin boxes в неделю) иногда по времени выгоднее брать предмет с меньшей diamond-эффективностью. Например, на spirit scroll монеты копятся около 3 недель, а на эквивалентный объем Diamond Box могут уйти месяцы.
