INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'character_additional_abilities',
  'character',
  'Additional Abilities',
  'Дополнительная информация о способностях
**Дополнительные способности**
1. Дизайн 3 предустановленных: рекомендуется 1x для Att 40%, 1x для 40% золота, 1x для 15% опыта.
2. Пресеты вступают в силу только в зависимости от того, какая страница открыта.
3. Для получения более подробной информации обратитесь к таблице, нажав на увеличительное стекло.
4. Нажмите на строку продвижения, чтобы закрепить ее и сохранить.
**Преимущества страниц атаки в промо по сравнению со страницами крита:**
*(этот конкретный пример основан на ранней стадии игры)*
Предположим, что 280% на странице убийцы, 140% на каждой сопутствующей странице, 100% на Элли Блесс, 50% на перчатках силы. Итого 570%

•Предположим, фиолетовая атака 9%/570%, увеличение урона на 1,5%.

• 10 тыс.% критического удара, примем еще 1 тыс. из-за реликвий и роста, всего 11 тыс.%

• Мифический бросок на крит = 50%?

• 50/11000 = увеличение урона в секунду на 0,45%.


• Фиолетовая атака > Синий крит.
