```
ДОПОЛНИТЕЛЬНЫЙ ЭЛЕМЕНТ Урон %
```
ДОПОЛНИТЕЛЬНЫЙ ЭЛЕМЕНТ Урон % =
(1 +
( РЕЛИКВИЯ ЭЛЕМЕНТА %
+ ПОНИМАНИЕ СОБСТВЕННИКА %
+ СОПУТСТВУЮЩИЙ ЭЛЕМЕНТ %
+ НАВЫКИ %
+ ЧЕРНЫЙ ШАР ТОП %
)
) * (1 +
( ЭЛЕМЕНТ СОЗВЕЗДИЯ %
+ ЭЛЕМЕНТ СТАТУИ ХАОСА %
+ ВСЕ ЭФФЕКТИВНЫЕ ЧЕРНЫЕ СФЕРЫ НИЖНЯ %
)
)

Где все переменные относятся к соответствующему элементу, который вы пытаетесь вычислить, а «ВСЕ ЭФФЕКТИВНЫЕ НИЖНИЕ ЧЕРНЫЕ СФЕРЫ %» — это все соответствующие % элемента и все Все % во всех 4 аксессуарах Black Orb.
```
ОКОНЧАТЕЛЬНЫЙ УБОР
```
ОКОНЧАТЕЛЬНЫЙ Урон =
(
НЕУСИЛЕННАЯ АТК * (1 - ШАНС КРИТИЧЕСКОГО УДАРА) * (1 - ШАНС СМЕРТЕЛЬНОГО УДАРА)
) + (
НЕУСИЛЕННАЯ АТК * КРИТИЧЕСКИЙ УРОН * СМЕРТНЫЙ УДАР * ШАНС КРИТИЧЕСКОГО * ШАНС СМЕРТНОГО УДАРА
) + (
НЕУСИЛЕННАЯ АТК * КРИТИЧЕСКИЙ УРОН * (ШАНС КРИТИЧЕСКОГО - (ШАНС КРИТИЧЕСКОГО * ШАНС СМЕРТНОГО УДАРА))
) + (
НЕУСИЛЕННАЯ АТК * Урон СМЕРТНОГО УДАРА * (ШАНС СМЕРТНОГО УДАРА - (ШАНС КРИТИЧЕСКОГО УДАРА * ШАНС СМЕРТНОГО УДАРА))
)
```
