INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'character_constellation',
  'character',
  'Constellation',
  'Разблокируется на Stage 1300 после завершения всех узлов [[character_memory_tree|Memory Tree]] и получения <:Nova:1276144888508977162>.

# Обзор

## Требования к разблокировке
* Открывается после получения **Nova**.
* Требуется завершить **Memory of Tree (Stage 1300+)**.

## Базовая система
* Вы можете **усиливать персонажа**, **гравируя звезды в созвездия**.
* Уровень Constellation of Light **растет** по мере **создания новых звезд**.
* Созвездия **открываются по очереди** в зависимости от **уровня Constellation of Light**.

> Созвездия по уровням, максимальная энергия каждого созвездия и количество звезд для каждого уровня.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/character/constellation/image.png
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/character/constellation/image.png
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/character/constellation/image.png

> Эффекты повышения уровня Constellation of Light.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/character/constellation/image.png

## Энергия звезд и бонусы
* Звезды создаются в Star Cradle.
* **После создания** звезды можно **гравировать в созвездия**.
* Каждая выгравированная звезда дает:
  * Дополнительную энергию звезд
  * Собственный бонус узла
* **Бонусы созвездия** зависят от **суммарной энергии звезд в этом созвездии**.
* Чем выше заполнение, тем сильнее эффект.

> Суммарный бонус ресурсов узлов (для детального разбора используйте Master Optimizer).
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/character/constellation/image.png

## Время крафта
* Создание звезд занимает время, и длительность растет с каждой попыткой, вплоть до 7x.

### Время крафта звезд
* Малые
1ч -> 2ч -> 4ч -> 12ч -> 24ч -> 36ч -> 48ч

* Средние
2ч -> 4ч -> 12ч -> 24ч -> 48ч -> 72ч -> 96ч

* Большие
48ч -> 192ч

## Оценка общей стоимости
8 x C19 <:class19:1055586742952018001>
22,800 Shards <:light_shard:1400147911526056067>
570,000 Stones на каждый элемент

## Стратегия крафта
Крафтите Small и Medium, ориентируясь на вариант с меньшим таймером в текущий момент. Medium эффективнее по ресурсам, но если вы ограничены по Stones, можно фокусироваться только на Small.
Large - опциональны и обычно не окупают тяжелые вложения: 12 уровень можно получить и без них.
Приоритет отдавайте completion-бонусам созвездий более высокого тира: по мере разблокировки переносите звезды из низких созвездий в более высокие.
