# Сверхчеловек (Superhuman)
У боев Superhuman есть 3 разные ротации.
### Ротация 1
Происходит в классах `1, 4, 7, 10, 13, 16, 19, 22, 25, 28`

<:skillbook:1055586814481678407> **Билд навыков**
<:SpeedSword:1054837558133129236> <:DemonHunt:1054837525799248034> <:PowerStrike:1054837360354938950> <:rave:1055598059628789772> <:EarthsWill:1054837582124560485>
<:Supersonic:1054837538793197628> <:Meditation:1054837527204352010> <:LightningBody:1054837662445469706> <:WrathofGoth:1054837540970057778> <:Rage:1054837629679575160>

<:noah:1060758788237443132> **Духи**
<:loar:1060758780775764058> <:noah:1060758788237443132> (<:radon:1060758791207002131> или <:sala:1060758775839080598>)

<:guide:1055587557976580106> **Механика и советы**
Как и в других вариантах, сферы периодически меняют фазу.
Первый фазовый переход дает отбрасывание (KB), и после этого каждый третий переход также будет с KB. Поэтому держите <:Supersonic:1054837538793197628> под эти моменты: используйте его прямо перед переходом сферы в фазу с отбрасыванием.
### Ротация 2
Происходит в классах `2, 5, 8, 11, 14, 17, 20, 23, 26, 29`

<:guide:1055587557976580106> **Механика и советы**
Как и в других вариантах, сферы периодически меняют фазу.

* Не эндгейм
<:skillbook:1290965217345540188> **Билд навыков (не эндгейм)**
<:SpeedSword:1054837558133129236> <:EarthsWill:1054837582124560485> <:BurningSword:1054837580388126721> <:Rage:1054837629679575160> <:Meditation:1054837527204352010>
<:HellfireSlash:1054837443347615796> <:FlameSlash:1054837335084236881> <:CurvedBlade:1054837628563890197> <:WrafofGod:1054837540970057778> <:DemonHunt:1054837525799248034>

<:noah:1060758788237443132> **Духи**
<:loar:1060758780775764058> <:noah:1060758788237443132> <:sala:1060758775839080598>

* Эндгейм
<:skillbook:1290965217345540188> **Билд навыков (эндгейм)**
<:SpeedSword:1054837558133129236> <:LightningBody:1054837662445469706> <:RedLightning:1054837517523882115> <:Rage:1054837629679575160> <:Meditation:1054837527204352010>
<:rave:1055598059628789772> <:WarriorBurn:1054837661195583558> <:CurvedBlade:1054837628563890197> <:WrafofGod:1054837540970057778> <:DemonHunt:1054837525799248034>

<:noah:1060758788237443132> **Духи**
Духи ротации: :LoarM: :ArkM: :RadonM:
### Ротация 3
Происходит в классах `3, 6, 9, 12, 15, 18, 21, 24, 27`

<:skillbook:1055586814481678407> **Билд навыков**
<:CurvedBlade:1054837628563890197> <:LightningBody:1054837662445469706> <:EarthsWill:1054837582124560485> <:Rage:1054837629679575160> <:BurningSword:1054837580388126721>
<:WrathofGoth:1054837540970057778> <:rave:1055598059628789772> <:DemonHunt:1054837525799248034> <:FlameSlash:1054837335084236881> <:Meditation:1054837527204352010>

<:noah:1060758788237443132> **Духи**
<:loar:1060758780775764058> <:noah:1060758788237443132> ( <:radon:1060758791207002131>, <:sala:1060758775839080598>)

<:guide:1055587557976580106> **Механика и советы**
Как и в других вариантах, сферы периодически меняют фазу.
В конце выполняется двойной <:DemonHunt:1054837525799248034> в окне <:rave:1055598059628789772> + <:noah:1060758788237443132> + <:WrathofGoth:1054837540970057778>.
**• Метод Double Rave (вариант для Strength)
<:skillbook:1055586814481678407> Навыки**
<:DemonHunt:1054837525799248034> <:Meditation:1054837527204352010> <:LightningBody:1054837662445469706> <:rave:1055598059628789772> <:EarthsWill:1054837582124560485>
<:HellfireSlash:1054837443347615796> <:FlameSlash:1054837335084236881> <:Rage:1054837629679575160> <:WrathofGoth:1054837540970057778> <:SpeedSword:1054837558133129236>

**Общая ротация навыков:**
Активируйте <:Rage:1054837629679575160> <:LightningBody:1054837662445469706> <:rave:1055598059628789772> <:DemonHunt:1054837525799248034> <:Meditation:1054837527204352010> <:DemonHunt:1054837525799248034> <:rave:1055598059628789772>.
Ровно через 20 секунд на таймере <:WrathofGoth:1054837540970057778>, когда он активирует pop <:Meditation:1054837527204352010> (заранее активируйте <:Rage:1054837629679575160> и <:LightningBody:1054837662445469706>), затем используйте <:DemonHunt:1054837525799248034> (2 раза, если возможно) после активации med.
В конце этого боя используйте <:Meditation:1054837527204352010>, если он доступен, и активируйте все навыки усиления, а также <:rave:1055598059628789772> непосредственно перед тем, как <:noah:1060758788237443132> снова сработает 2x <:DemonHunt:1054837525799248034>, после чего наступит рейв.

**Важные требования**
Нужен <:Meditation:1054837527204352010> примерно 3/4 уровня.
Нужен Water cooldown stone тира B.

Если у вас есть <:sala:1060758775839080598> и вы хотите использовать его максимально эффективно, удерживайте свой первый <:rave:1055598059628789772> до ~7,5 секунд, вы также не сможете использовать <:Meditation:1054837527204352010> в первом рейве и должны полагаться на скорость атаки для двойного DH, остальную часть ротации навыков можно оставить как есть.

Если у вас есть e5 <:ark:1060758770373886002>, именно эту сборку можно использовать и на Strong Heart.
