### Фазы
Все бои Superhuman циклично проходят через 3 фазы: Yellow, Blue и Red.

Yellow-фаза в начале лечит, а затем получает дополнительный урон от ваших ударов во время этой фазы.
Blue-фаза в начале отбрасывает персонажа и далее получает обычный урон.
Red-фаза значительно снижает входящий урон по сфере, включая урон от релиза rave.

### Варианты
У боев Superhuman есть 3 варианта (главное отличие - стартовая фаза и фаза WoG/Noah, они фиксированы для каждого варианта):
Blue SH / вариант 3n + 1 / Ротация 1 - 1, 4, 7, 10...: старт, WoG и Noah приходятся на Blue-фазу. Полезно использовать <:Supersonic:1054837538793197628>, чтобы избегать отбрасываний в ключевые окна.
Red SH / вариант 3n + 2 / Ротация 2 - 2, 5, 8, 11...: старт, WoG и Noah приходятся на Red-фазу. Noah стартует чуть раньше начала Red-фазы, поэтому выгодно использовать Ku fam и заранее подготовить запись rave под это короткое окно.
Yellow SH / вариант 3n / Ротация 3 - 3, 6, 9, 12...: старт, WoG и Noah приходятся на Yellow-фазу. Здесь подходит более стандартная ротация, так как слабая фаза совпадает с burst-окнами. Основной урон отдавайте после финального лечения.
### Ротация GK HP Triple Rave
