INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'character_growth',
  'character',
  'Growth',
  'Приоритеты системы Growth.

<:dragonatk:1055586248552628274> **Приоритет Growth:** CRIT > Luck > STR > ACC > Dodge.
Если вы новичок и не хватает урона, в начале лучше сочетать CRIT и Luck.

## Формулы статов Growth

### СИЛА (STR)
```формула
"TOTAL STR BONUS" = ("STR BASE VALUE" + ("CURRENT SLAYER LEVEL" - 250) * ("TOTAL LATENT STR" / 200)) * "CURRENT STR GROWTH LEVEL"  # Итоговый бонус STR
```

### ЗДОРОВЬЕ (HP)
```формула
"TOTAL HP BONUS" = ("HP BASE VALUE" * (1 + ("CURRENT SLAYER LEVEL" - 250) / 1000 * "TOTAL LATENT HP")) * "CURRENT HP GROWTH LEVEL"  # Итоговый бонус HP
```

### ВЫНОСЛИВОСТЬ (VIT)
```формула
"TOTAL VIT BONUS" = ("VIT BASE VALUE" + ("CURRENT SLAYER LEVEL" - 250) * ("TOTAL LATENT VIT" / 200)) * "CURRENT VIT GROWTH LEVEL"  # Итоговый бонус VIT
```

### КРИТ (CRIT)
```формула
"TOTAL CRIT BONUS" = "CRIT BASE VALUE" * (1 + ("CURRENT SLAYER LEVEL" - 250) / 10000 * "TOTAL LATENT CRIT") * "CURRENT CRIT GROWTH LEVEL"  # Итоговый бонус CRIT
```

### УДАЧА (LUK)
```формула
"TOTAL LUK BONUS" = "LUK BASE VALUE" * (1 + ("CURRENT SLAYER LEVEL" - 250) / 20000 * "TOTAL LATENT LUK") * "CURRENT LUK GROWTH LEVEL"  # Итоговый бонус LUK
```
