INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'character_latent_power',
  'character',
  'Latent Power',
  'Приоритеты Latent Power.

# Гайд по Latent Power

## Обычный Latent Power
**Цель:** закрыть все важные статы на каждой странице (всего 5 страниц).

1. Используйте Normal Reset, пока не получите STR 10 / CRIT 10 на всех страницах. Advanced Reset тоже допустим для стабильности, но в среднем он дороже (менее эффективен).
2. Приоритет: CRIT > STR (если нужно выбирать, оставляйте Crit).
3. После максимизации STR/CRIT Latent Power можно больше не трогать. Пытаться отдельно добивать LUK/HP/HP REC обычно невыгодно; они добираются естественно после прохождения дракона (примерно Stage 1500).

## Пробужденный Latent Power
* Открывается на <:dragonos:1060039754382585856>
* Базовое правило: всегда выбирайте более дешевый вариант ignite между single ignite и random ignite. Random немного сильнее при количестве sparks меньше 5 (потому что вы не теряете прогресс), а single ignite немного сильнее, когда до заполнения полосы ignite остается меньше 5 sparks (чтобы не терять часть потенциальной выгоды от крупного random-ролла).

### Одиночный Ignite vs Random Ignite
* Single ignite имеет фиксированную стоимость на любом awaken-уровне и всегда дает 1 dragon spark.
* Random ignite стоит от 50% до 150% от single ignite и в среднем тоже дает 1 dragon spark. Но фактический результат может быть от -5 до +5 sparks из-за RNG.
* По таблице ниже:
  - [Row 0] Sparks = 0 и Random Ignite лишь немного дороже -> Random лучше
  - [Row 1-15] Sparks <= 15 и Random Ignite дешевле -> Random лучше
  - [Row 2-15] Random Ignite дороже -> Single Ignite лучше
  - [Row 16-20] Sparks > 15 -> Single Ignite лучше

> Ожидаемое количество Dragon Sparks от random ignite
