VALUES (
  'character_memory_tree',
  'character',
  'Memory Tree',
  'Информация о системе Memory Tree.

https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/character/memory_tree/Screenshot_2024-06-19_221843.png

**Требование к разблокировке**
Требуется <:Seed:1174921381201330276> (C20 12*).

**Общая информация**
Потребление Memory Essence усиливает разные ресурсы: опыт, золото, кубы, кости, Dragon Essence и Mana Crystals. При усилении эффект может работать либо глобально, либо только в конкретных местах: стадии, Closed Mine, Training Cave, Sleeping Flame, Dimensional Rift, Forest of Circulation.

Everyday Ad Watch может сокращать таймер на 30 минут x 4, либо можно ускорять за Dia (10 раз). 1 секунда = 1 Dia.

Каждый узел обычно усиливается только один раз, если не открыты дополнительные узлы. Memory Essence получается за прохождение каждых пяти стадий. Для повышения уровня Memory Tree нужно выполнять условия Level Up. Чем сильнее дерево, тем выше бонусы к Extra ATK, HP и HP regeneration.

При выполнении условий breakthrough вы получаете дополнительные Promotion ATK, HP и рост максимального уровня. Все улучшения внутри дерева ограничены по времени: от 1 часа до 24 часов.

Эффекты прорыва:

