INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'character_training_diary',
  'character',
  'Training Diary',
  'Разбивка дневника тренировок
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/character/training_diary/20182150ZXQkR1Lc.gif
**Развитие навыков дневника тренировок**

**Навыки**
Ранняя/Средняя игра
<:SpeedSword:1054837558133129236> <:EarthsWill:1054837582124560485> <:HellfireSlash:1054837443347615796> <:GigaStrike:1054837450415022140> <:FireSword:1054837553951416431>
<:BurningSword:1054837580388126721> <:CurvedBlade:1054837628563890197> <:FlameSlash:1054837335084236881> <:IronWill:1054837555482341487> <:FlowingBlade:1054837613074321561>

Поздняя/конец игры
<:SpeedSword:1054837558133129236> <:DemonHunt:1054837525799248034> <:rave:1055598059628789772> <:Meditation:1054837527204352010> <:FlameSlash:1054837335084236881>
<:CurvedBlade:1054837628563890197> <:WrafofGod:1054837540970057778> <:BurningSword:1054837580388126721>/ <:WarriorBurn:1054837661195583558> <:EarthsWill:1054837582124560485> <:HellfireSlash:1054837443347615796>

**<:noah:1060758788237443132> Духи**
<:noah:1060758788237443132> предпочтительнее, но подойдет любой пробужденный/высокий уровень духа.

**Советы**
Если вы не можете получить два dh под wog Rave, переместите медитацию, чтобы заменить Powerstrike и включить сильный поток, Ручную охоту на демонов и Rave.

Для сборки без DH/Rave со слотами 9/8/7 возьмите <:FireSword:1054837553951416431> <:IronWill:10548375555482341487> <:FlowingBlade:1054837613074321561> соответственно.

**Отказ от ответственности**
Вы можете выйти из боя и вернуться в него без штрафа.

Духи, наносящие % урона, такие как Сала, лоар и радон, не будут работать. Лучше всего использовать Ноя. Если ark и herh имеют низкий уровень, используйте двух духов самого высокого уровня.
**Для дневника тренировок**:
1. Каждые 2000 полосок урона, нанесенного «NPC-дневнику тренировок», Сепиру. Вы получите 20 SP, что в общей сложности составит 100 SP каждые 10 000 баров. По завершении вы также получите 20 OP (очки сверх). Каждые 5 очков увеличивают атаку, здоровье, скорость записи здоровья или максимальный уровень золота на 25. Каждое 1 очко увеличивает максимальный уровень критического удара, точности или уклонения на 5.

2. Все уровни Дневника тренировок в боях против Сепира будут иметь 10000 баров хп. (Сложность боев увеличивается по мере повышения уровня.)
После того, как вы победите босса и перейдете на следующий этап, вы получите 20 ОП, и полоска сбрасывается до 0.

3. Победа на этапе автоматически увеличивает ваши пределы роста силы, здоровья, здоровья и золота на 50, а точность уклонения от критического удара - на 10.

4. Вы не можете распределить все очки на один стат, на каждом пройденном этапе (10000 полосок) вы увеличиваете максимальный предел роста силы hp hp и золота на 50, а точность уклонения от критического удара - на 10.

5. Рекомендация — Крит > Сила > Точность > Уклонение > Золото.
**Для тренировочного манекена**
- Доступно после того, как вы очистите 10000 в Дневнике тренировок.
- Ежедневно повреждайте тренировочный манекен, чтобы получить дополнительный опыт. Вы можете использовать предыдущие сборки Дневника тренировок или сборки сценического босса. Манекен может нанести вам урон, поэтому будьте осторожны с использованием <:Rage:1054837629679575160>.
