VALUES (
  'companion_advancement_battles',
  'companion',
  'Advancement Battles',
  'Информация о битвах продвижения с компаньонами.
Возможны изменения с учетом Skill Mastery.

**Битвы продвижения**
- Для каждого компаньона нужен свой набор навыков.
- Если не получается пройти - сначала усилите аккаунт.
- Терпение и фарм.
- Готовые сборки навыков: <#1052865880146579469>.
- Страницы 1-2: нельзя использовать против компаньона навыки его элемента.
- Страницы 3-4: у компаньона появляются новые способности. Если использовать против него навыки того же элемента, он получает щит.

**Способности**
- Ellie: отбрасывает, наносит высокий урон.
- Zeke: отбрасывает игрока, создает столб, который нужно разрушить. Пока столб стоит, Zeke лечится.
- Miho: 100% уклонение, высокий урон.
- Luna: отбрасывание и блок навыков.

**Смотрите также**
- <#1129927350683959326> - Mystic-видео для боев на более высоких страницах.

**Бой с компаньонами**
