INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'companion_beast',
  'companion',
  'Beast',
  'Разблокируется после Warfrost.

# Руководство по зверям
* Магазин обновляется по ежемесячному, еженедельному и ежедневному таймерам.

## Приоритет трат
* Еженедельные закуски > Ежемесячные свистки > [ОПЦИОНАЛЬНО] Еженедельные свистки > [ОПЦИОНАЛЬНО] Ежедневные свистки
* Покупать фрукты обычно невыгодно. Обычные товары тоже не стоят покупки (только <:worrywhale:1083099023415713895>).

## Свистки
* Используются для призыва зверей.

## Закуски
* 1 закуска + 1 свисток = гарантированный зверь из категории закуски.
* Выше шанс получить Unique.

## Фрукты
* Дают мгновенную привязанность.

# Система зверей

## Пробуждение
* Усиливает навык зверя и его собственные эффекты.
* A1-A5 требуют по 1 копии, A6 требует 2 копии (база + пробуждения = 8 копий всего).

## Привязанность (уровень зверя)
* Увеличивает собственные эффекты.

### Рекомендуемый порядок прокачки

1. Draco (сначала все до 10 уровня → потом все до 20 → потом до максимума) **-- пропустите этот шаг, если вы оффлайн или не используете ежедневного маунта --**
2. Golems (сначала все до 10 уровня → потом все до 20 → потом до максимума) **-- пропустите этот шаг, если вы оффлайн или не используете ежедневного маунта --**
3. Unique звери (сначала все до 10 уровня → потом все до 20 → потом до максимума)
4. Остальные звери, от самого высокого пробуждения к самому низкому (сначала все до 10 уровня → потом все до 20 → потом до максимума)

> **Почему?**
> **Уровни 1–10** стоят 300 привязанности за уровень (самые дешёвые)
> **Уровни 11–20** стоят 400 привязанности за уровень (дешевле)
> **Уровень 21+** стоит 500 привязанности за уровень
> **Draco + Golems** → увеличивают привязанность, получаемую от верховой езды
> **Unique** → имеют более сильные собственные эффекты
> **Более высокое пробуждение** → имеют более сильные собственные эффекты

> Эффект навыка каждого зверя в зависимости от пробуждения (A0-A6)
![image](assets/media/guides/companion/beast/image.png)

## Верховая езда
* Длительность: 2 часа в день
* Даёт привязанность выбранному зверю
* Используйте во время ежедневного фарма (со свитками)
* Влияет только на фарм стадий

## Разведка
* Бесплатные ежедневные награды: черника и случайный шанс на камни / алмазы / изумруды / кости / снаряжение L4+ / перья / и т. д.
* КД 8 часов
* Обычно авто-заполнение идеальное, но иногда его нужно подстроить. Проверьте на своём аккаунте.

## Стратегии трат на зверей
* Самый дешёвый вариант: покупать еженедельные закуски + ежемесячные свистки, пока не соберёте всех зверей, затем покупать еженедельные закуски + минимальное число ежемесячных свистков для расхода закусок.
* Еженедельные и ежедневные свистки можно использовать для ускорения закрытия зверей, но это немного повышает среднюю общую стоимость.
* Ниже есть данные симуляции для сравнения.

### Стоимость разных стратегий покупки свистков
Поскольку разброс из-за RNG большой, вот симуляция, которую Leoht использовал для этих данных:
https://www.online-python.com/tAboFORrNs
Чтобы найти лучшую стратегию под свой аккаунт, меняйте только первые 4 переменные сверху.

> Примечания:
> Hybrid_X → используйте ежемесячные свистки для призыва зверей, пока не достигнете X жетонов зверей, затем используйте свистки только вместе с закусками.
> Обычно стратегия нацелена на получение pity-зверей с минимальным необходимым числом жетонов (1000 жетонов зверя на каждого), а не на накопление большого запаса.
![image](assets/media/guides/companion/beast/image2.png)

### Стоимость фруктов зверей
0️⃣ >>>> 7️⃣ 0️⃣

🫐 Blueberries = 3170
🍑 Peach = 317
⭐ Starfruit = 27 (даёт 700 exp)

