INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'companion_companion_guide',
  'companion',
  'Companion Guide',
  'Мнение убийцы
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/companion/companion_guide/1_5.png
## Элли (Ellie) 🌬️
1+2. Гимн эльфа / Песнь эльфов — рекомендуется дойти до ~50 гимна, а затем до максимальной песни эльфов, а затем закончить Гимн. Здесь довольно гибко, потому что оба чрезвычайно важны.
3. Взаимодействие с ветром — хороший бонус для фарма + статистика FoC.
4. Песня ветра - Больше зеленых душ
5. Прикосновение духа. Может иметь приоритет, равный зеленым душам, если вы регулярно используете Зеленый SW, или использоваться в качестве небольшого увеличения урона при использовании 1-го зеленого SW.
-# все ниже не так критично, комбинируйте под свои потребности
6. Интенсивный огонь – дешевые уровни/мастерство компаньонов. При необходимости могу сделать раньше.
7. Обнаружение слабости — увеличение урона в разломе.
8. Благословение леса - довольно плохо для атаки, потому что оно попадает в страницы продвижения компаньонов и убийц, а также мастерство навыков, реликвии и все другие источники «дополнительной АТК».
9. Понимание ветра

## Зик (Zeke) 🪨
1+2. Мудрость пластичности + Танец клинков — это сложная задача, потому что кубы — это бесплатный ресурс, который наносит хороший урон на ранней стадии, а Танец клинков — действительно хороший источник урона (независимый множитель в формуле урона). Как и Элли, может разделить ~50 уровней на «Пластичность», затем на максимальный BD, а затем вернуться назад, чтобы закончить «Водопровод».
3. Взаимодействие с Землей. Хорошее повышение статистики. Духи земли важны для боссинга и промоушена.
4. Улов души – важен для обращения души.
-# все ниже не так критично, комбинируйте под свои потребности
5. Беспорядок — больше перебросов гравюр SW.
6. Стойкость - в основном для дешевого мастерства. Можно повысить уровень раньше, если отчаянно не хватает здоровья (должно быть редко)
7. Блокировка. Выживание никогда не является проблемой в Рифте (обычно либо погибает мгновенно, либо время истекает). Может быть полезен для Origin of Chaos или Destructionist в поздней игре.
8. Лунатик - совершенно бесполезен для ДМГ. Делайте это только для оттачивания навыков. Если вам не нужно более быстрое освоение навыков, сначала прокачайте Понимание Земли.
9. Понимание Земли
## Михо (Miho) 🔥
1. Шаг тени – полезен для выживания на ранних этапах продвижения по службе.
2. Золотая лихорадка 2 — отличный прирост золота
3. Общение Пламени – Хорошее повышение статистики.
4. Красная жадность — красные души самые важные, прокачивайте как можно раньше.
5. Кастинг – хорошо, если вы используете Red SW.
-# все ниже не так критично, комбинируйте под свои потребности
6. Золотая лихорадка 1. Золото полезно, хотя оно и дорогое.
7. Теневое клеймо — увеличение урона в разломе.
8. Танец теней — можно отдать приоритет танцу теней, если вам нужно мастерство (бесполезно для уклонения)
9. Понимание Пламени

## Луна (Luna) 🌊
1. Mana Dope — необходим для фарма билдов/использования fulgurous или других навыков, требующих много маны.
2. Мудрость войны - солидный прирост урона. Хуже, чем «Танец клинков», но все равно полезно.
3. Взаимодействие с морем. Хорошее повышение статистики фарма, поскольку Тодд часто используется в фарме (и, в конечном итоге, Луга для TC).
4. Песня глубокого моря. Синие души являются наименее важными душами, потому что они дают наименьший импульс при отдаче приоритета слезам красных душ или фарме зеленой области душ. Итак, души полезны, но не существенны.
5. Магия рун. Может иметь приоритет, равный Синим душам, если вы регулярно используете Синий SW, или использоваться в качестве небольшого увеличения урона при использовании 1-го Синего SW.
-# все ниже не так критично, комбинируйте под свои потребности
6. Гимн Бездны – полезно для опыта
7. Block Magic — увеличение урона в разломе.
8. Усиление маны – не обязательно, в основном просто качество жизни для борьбы с разломами. При необходимости можно прокачать до 50/60 раньше.
9. Понимание моря
