INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'disclaimer_disclaimer',
  'disclaimer',
  'Disclaimer',
  'Игра развивается, рекомендуемые сборки будут соответствующим образом адаптироваться. Мы заложили основу, но каждый игрок сам должен решить, что ему подходит лучше всего. Учитывая множество факторов, универсального решения не существует.

Оптимальный путь обновления будет зависеть от индивидуальной удачи, предпочтений и стиля игры. Каждая комбинация персонажей и снаряжения имеет свои уникальные преимущества и недостатки.

**Управление этим сервером - наша страсть, и мы относимся к нему как к хобби, а не как к работе.**

**Эксперименты с разными сборками критически важны, если вы хотите раскрыть максимум потенциала в игре.**

<#1125060841155334234> <#1124554406810095616> <#1370965509306191892> <#1370965595306065930> <#1370965689657196575>

Хорошего дня.
