VALUES (
  'early_game_promotions_mithril',
  'early-game-promotions',
  'Mithril',
  'Сборка для промо-акции Mithril <:mithril:1054852906903425035>
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/early-game-promotions/mithril/mithril.gif
**Информация о битве продвижения**
Вы должны уничтожить 500 мобов в течение примерно 1 минуты, каждый 10-й моб — это более крупный моб с увеличенным количеством здоровья.

<:skillbook:1290965217345540188> **Развитие навыков**
<:Fulgurous:1054837528714293288> <:Flamewave:1054837524343824444> <:ThunderboltSlash:1054837459994812426> <:RedLightning:1054837517523882115> <:SpeedSword:1054837558133129236>
<:CurvedBlade:1054837628563890197> <:IronWill:1054837555482341487>

<:noah:1060758788237443132> **Духи**
<:zappy:1060758779488112701> <:mum:1060758787092402237> <:kart:1060759190672515092> <:radon:1060758791207002131> (предпочтительно использовать любой из них.)

<:guide:1055587557976580106> **Советы:**
Эта сборка основана на предположении, что у вас достаточно урона для одного выстрела по мелким мобам с помощью Fulgurous ( <:Fulgurous:1054837528714293288> ).
