INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'equipment_accessories',
  'equipment',
  'Accessories',
  'Информация об аксессуарах

Существует шесть уровней аксессуаров, которые можно **получить** или **создать**:
- **Обычный** (Common)
- **Хороший** (Great)
- **Редкий** (Rare)
- **Эпический** (Epic)
- **Легендарный** (Legendary)
- **Мифический** (Mythic)

Каждый уровень имеет четыре ранга (Grade 1-4), причём ранг 4 является самым сильным. По мере повышения ранга увеличение HP от аксессуаров становится более значительным.

Существует седьмой уровень аксессуаров, эксклюзивный для крафта путём объединения 5 M1 в чёрный обелиск. Уровень: **Бессмертный** (Immortal).

Восьмой уровень аксессуаров доступен через объединение, пробуждение и затем скрытое пробуждение чёрного обелиска. Уровень: **Древний** (Ancient).

Количество M1, необходимое для **объединения**, **пробуждения** и **скрытого пробуждения**:

5x <:M1:1211868018590879864> = <:orb:1127994010422739075>
1* = 1x <:M1:1211868018590879864>
2* = 1x <:M1:1211868018590879864>
3* = 1x <:M1:1211868018590879864>
4* = 1x <:M1:1211868018590879864>
5* = 1x <:M1:1211868018590879864>
6* = 4x <:M1:1211868018590879864> = <:orb6:1378271019399385209>
7* = 1x <:M1:1211868018590879864>
8* = 1x <:M1:1211868018590879864>
9* = 1x <:M1:1211868018590879864>
10* = 1x <:M1:1211868018590879864>
