https://discord.com/channels/1052865879609724968/1350505589603700756
**Что делать с аксессуарами**
Получите Orb и Mantra до открытия Warrior Burn. Рекомендуемая последовательность:
<:M1:1211868018590879864>: <:StrongCurrent:1054837556778373120> → <:WrathOfGods:1054837540970057778> → <:orb:1127994010422739075> → <:Mantra:1054837329367420998> Lv1 → <:LightningBody:1054837662445469706> → <:Mantra:1054837329367420998> Lv5 → <:WarriorBurn:1054837661195583558> → <:orb6:1378271019399385209> → <:Nova:1276144888508977162> → <:light_shard:1400147911526056067> → Древние духи → Созвездия → Овладение навыками → <:orb24:1378271179365814425>
