INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'equipment_black_orb',
  'equipment',
  'Black Orb',
  'https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/black_orb/image.png
Требование:
Победить <:blackmythril:1060039750913888296> и получить <:orb:1127994010422739075>
## Обзор
Черная сфера (Black Orb, часто говорят blorb) дает общий прирост стихийного урона через основные и усиливающие характеристики.
Для каждого элемента используется отдельный аксессуар Black Orb.
## Черная мана
Черная мана - ресурс для призыва аксессуаров Black Orb. Ее можно получать 3 раза в день (1 бесплатно и 2 за рекламу). Всегда забирайте всю доступную ману, чтобы максимизировать число призывов в день.

Количество получаемой черной маны растет каждые 20 этапов (при входе в новый регион). При этом с уровнем Black Orb растет и стоимость призыва в черной мане. Поэтому уровень Black Orb нужно держать в балансе с вашим текущим максимальным этапом: если перекачать слишком рано, число призывов в день станет слишком низким.

Обычно комфортная точка - примерно 150-450 роллов в день (по предпочтению игрока: больше роллов требует больше времени, меньше роллов дает меньше вариантов).

После Black Orb 24 можно повышать уровень сразу по мере возможности благодаря наследованию характеристик.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/black_orb/image.png
## Призыв и характеристики:
Вы можете призывать по x1, x10 или x30, тратя черную ману.
Базовая рекомендация по приоритету статов:
- Fire: усиление огня (Amplify Fire%)
- Wind: Amplify Wind% или Amplify All%
- Earth и Water: Amplify All%

В поздней игре и при высоком Skill Proficiency (200+) приоритет обычно смещается в сторону Earth + Wind.

Рекомендуемые фильтры на старте:
Легендарный
2x Огонь или 2x Все

На Black Orb 20 можно переключаться на:
Мифический
Ветер: 3x Ветер или 2x Все
Земля: 3x Земля или 2x Все
Огонь: 3x Огонь или 2x Все
Вода: 2x Все
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/black_orb/image.png
## Резонанс Черной сферы:
Разблокируется на уровне Black Orb 16.
Суммарные уровни отдельных аксессуаров дают бонусы к характеристикам. Важно не застревать на слишком низких уровнях отдельных частей.
Небольшой бонус вы получаете каждые 2 уровня.
ATK и HP работают как независимые множители, Amplify складывается с текущим бонусом усиления элемента.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/black_orb/image.png
## Пробуждение Черной сферы:
Разблокируется на 20-м уровне Черной сферы.

Количество Dark Fragments зависит от числа пробуждений <:orb:1127994010422739075> выше базового уровня.
Стартово вы получаете 3.
Фрагменты, полученные за сферу:
1-5: 1 фрагмент
6: 4 фрагмента
7-11: 1 фрагмент
12: 4 фрагмента
13-17: 1 фрагмент
18: 4 фрагмента
19-23: 1 фрагмент
24: 4 фрагмента
При пробуждении отдельных частей сначала усиливайте ваш главный элемент для боссинга и промо: обычно Fire (early-lategame) или Earth (endgame).

Каждое пробуждение дает +1 к случайной линии Amplify. На 6* дополнительно +1 ко всем линиям (итого +9 линий).

Усиление пробуждения, бонус к характеристикам и стоимость:
1\*: +10%, +1 линия, 1 фрагмент
2\*: +10%, +1 линия, 2 фрагмента
3\*: +10%, +1 линия, 1 фрагмент
4\*: +10%, +1 линия, 2 фрагмента
5\*: +10%, +1 линия, 1 фрагмент
6\*: +20%, +4 линии, 5 фрагментов

https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/black_orb/image.png
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/black_orb/image.png
## Бонусный эффект:

Разблокируется на уровне 24.

Эта часть важна в основном при наличии выраженного основного элемента (чаще Fire в early-lategame или Earth в endgame).
Бонус зависит от количества линий, совпадающих с базовым элементом.

На остальных трех элементах бонус обычно не является целью, так как там чаще собирают 4 линии Amplify All Attributes Dmg 7%.
## Наследование характеристик
Разблокируется на уровне Black Orb 24.

С этого уровня можно переносить 1 предыдущий ролл Amplify на следующий аксессуар. Это заметно упрощает сохранение 7% роллов, переход к более высоким основным статам и общий рост резонанса.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/black_orb/image.png
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/black_orb/image.png
Дополнительный урон Black Orb по боссам по уровням:
Ур. 3, 8, 12, 16, 20 — увеличение урона по боссу на 50%, увеличение здоровья на 100%
Ур. 24, 29, 33, 39, 45, 51 — увеличение урона по боссу на 100%, увеличение здоровья на 200%

Все прочие промежуточные уровни дают Extra Monster 20% Damage и 40% HP Recovery.
Исключения: уровни 30, 31, 32 дают Extra Monster 30% Damage и 60% HP Recovery.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/black_orb/image.png
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/black_orb/image.png
