VALUES (
  'equipment_light_shard',
  'equipment',
  'Light Shard',
  'Информация об осколках света

# Что такое осколки света?
Осколки света - это специальная валюта в игре, которую получают при разборке оружия, аксессуаров и классов.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/light_shard/image.png
Количество получаемых осколков зависит от таблицы вероятностей на изображении.

# Сколько осколков света нужно?
* **10 000 осколков света** на каждую цель:
* Пробуждение **Orr** до **24 звезд** <:OrrBase:1055585922177040454>
* Пробуждение **Orb** до **24 звезд** <:orb24:1378271179365814425>
* Пробуждение **Class** до **Nova** <:Nova:1276144888508977162>
* **1 000 осколков света** на пробуждение **каждого духа** до **Ancient**
<:light_shard:1400147911526056067>
Осколки света имеют лимит 10k. Можно иметь больше 10k, но если попытаться разбирать предметы при 10k+ осколков, игра не позволит это сделать.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/light_shard/image-14.png
* Если вы специально призываете m1/c19 ради осколков, обычно выгоднее тратить на это m1: в долгосроке соотношение алмазы/осколки лучше, а m1 доступнее. Иначе можно просто фармить 18mpw.
