VALUES (
  'equipment_relics',
  'equipment',
  'Relics',
  'Информация о реликвиях
**Когда призывать реликвии?**
Новому игроку в этом нет необходимости, пока вы не дойдете до Адаманта, поскольку большую часть контента можно пройти, просто призывая более сильных духов или мечи, согласно <#1266503499009753110>.

**Рекомендуемые уровни реликвий:** 
<:adamant:1054852905020170390>/<:ether:1060039749336830002> 30-50 ур.
<:blackmythril:1060039750913888296> 50+ ур.
<:demonmetal:1060039752704864336>-<:ragnablood:1060039755561193562> 100 ур.

Реликвии дают дополнительные характеристики на каждом 10-м уровне, за исключением реликвий скорости атаки.

Переход `39 -> 40` сам по себе более ценен, чем `35 -> 39`.

Перчатки силы (АТК) и Глаз охотника (крит) — самые важные реликвии.

Это означает, что если ориентир - 30-й уровень, то и «Перчатки силы», и «Глаз охотника» должны быть *минимум* 30-го уровня; остальные реликвии могут быть любого уровня.

Когда крит и сила достигнут 100, вы можете остановить реликвии, поскольку ценность остальных незначительна.
