VALUES (
  'equipment_sealed_shrine',
  'equipment',
  'Sealed Shrine',
  '# Что такое запечатанный храм?

Запечатанный храм открывается после победы над Рагнабладом <:ragnablood:1060039755561193562>

* Уровень 1 у статуй не дает эффекта.
* Для улучшения статуй используются разные валюты с разными бонусами.
  * Все стоимости валют и шансы бонусов сбрасываются ежедневно, прогресс жалости сохраняется.

## Статуя дракона (Statue of Dragon):
* Открывается на 1 ранге Awaken Latent Power
  * Лимит уровня увеличивается с каждым рангом
* Стоимость: [[equipment_sealed_shrine|Dragon Sparks]]
Повышает характеристики роста.
Каждый 5-й уровень — это усиление критического удара, дающее хороший урон.
Стоимость обновления может быть очень высокой, выравнивайте ее относительно вашего дохода от Искры Дракона, поскольку вы не хотите жертвовать пробуждением.

## Статуя хаоса (Statue of Chaos):
* Открывается на Chaos Level 10
  * Лимит уровня увеличивается каждые 10 уровней хаоса
* Стоимость: [[equipment_sealed_shrine|Chaos Souls]]
Повышает ATK оружия души и ATK персонажа.
Стоимость обновления средняя, ​​вы можете получить максимальную сумму за несколько дней.

## Статуя демона (Statue of Demon):
* Открывается на Mana Altar 30
  * Лимит уровня увеличивается за каждую звезду алтаря
* Стоимость: [[equipment_sealed_shrine|Soul Marbles]]
Повышает HP и урон навыков.
Стоимость обновления может быть очень высокой, выравнивайте ее относительно вашего дохода от Soul Marble.

## Статуя порядка (Statue of Order):
* Открывается на Black Orb Lv. 1
  * Лимит уровня увеличивается с уровнем Black Orb
* Стоимость: [[equipment_black_orb|Black Mana]]
Увеличивает стихийный урон.
Стоимость обновления невелика, вы можете максимизировать ее, когда это возможно.
