  'equipment_skill_stone',
  'equipment',
  'Skill Stone',
  'Информация о камнях умений
# Камни навыков
## Основная информация
* Кнопка «Камень навыков» открывается на уровне 400.
* Существует 3 формы камней, каждая из которых дает уникальный положительный эффект:
> Перезарядка (Треугольник)
> Продлить продолжительность навыка (квадрат)
> Меньшее количество ударов (Алмаз)
* Для каждой фигуры есть 4 варианта, по одному на каждый элемент.
* Камни начинают открываться на этапе 360, и вы открываете по одному камню каждые 20 этапов (360... 380... 400... и т. д.)
* Каждая форма имеет 2 типа
> **Тип А**: 4%
> **Тип B**: 7%
* С 360 по 580 вы получаете все камни **Типа**.
* С 600 по 800 вы получаете все камни **Типа B**.

## Базовые настройки
Фермерство: 3 камня ветра
Сражается с <:Meditation:1054837527204352010>: камнем восстановления воды.
Сражается в основном с помощью <:Rage:1054837629679575160>: камня времени огня.
Сражается с <:WrathOfGods:1054837540970057778>: земным камнем времени.
Тепловой камень: элемент вашей основной атаки, основанной на ударе, в этом контенте.

## Камень п/ Этап
### **Тип**
* 360 -> Камень восстановления (Огонь - Тип A)
* 380 -> Камень восстановления (Вода — тип A)
* 400 -> Камень восстановления (Ветер — тип A)
* 420 -> Камень восстановления (Земля — тип A)
* 440 -> Камень Времени (Огонь — Тип)
* 460 -> Камень Времени (Вода — Тип)
* 480 -> Камень Времени (Ветер — Тип)
* 500 -> Камень Времени (Земля — Тип)
* 520 -> Камень Жарки (Огонь - Тип A)
* 540 -> Тепловой камень (Вода — тип A)
* 560 -> Камень тепла (Ветер — Тип)
* 580 -> Камень Жарки (Земля — Тип A)

## **Тип B**
* 600 -> Камень восстановления (Огонь - Тип B)
* 620 -> Камень восстановления (Вода — тип B)
* 640 -> Камень восстановления (Ветер - Тип B)
* 660 -> Камень восстановления (Земля - ​​Тип B)
* 680 -> Камень Времени (Огонь - Тип B)
* 700 -> Камень Времени (Вода - Тип B)
* 720 -> Камень Времени (Ветер - Тип B)
* 740 -> Камень Времени (Земля - ​​Тип B)
* 760 -> Камень Жарки (Огонь - Тип B)
* 780 -> Тепловой камень (Вода - Тип B)
* 800 -> Камень тепла (Ветер - Тип B)
* 820 -> Камень Жарки (Земля - ​​Тип B)
