VALUES (
  'equipment_soul_weapon_engraving',
  'equipment',
  'Soul Weapon Engraving',
  '# Руководство по гравировке оружия души

## Что такое гравировка оружия души?
Гравировка Оружия Души — это функция, которая позволяет вам повысить **% АТК** вашего Оружия Души и получить **дополнительные характеристики**, помещая на игровое поле драгоценные камни душ, подобные тетрису. Завершение доски дает мощные **бонусы к ATK% и HP%**.

## Разблокировка гравировки
Система гравировки Оружия Души становится доступной после того, как вы **создадите Оружие Души «Гордость»** или любое **Оружие Души более высокого уровня**.
После его создания вы разблокируете **Гравировальную доску**, что позволит вам начать улучшать свое Оружие души с помощью Камней души.

## Как это работает

### 1. Фарм душ хаоса
* Вы можете убивать до **1 000 мобов в день**, чтобы получать души хаоса.
* Чем **сильнее** ваше оружие души, тем **больше душ хаоса** вы получаете за день.
* Чем **больше душ хаоса** вы тратите, тем выше становится ваш **уровень хаоса**.
* Более **высокий уровень хаоса** увеличивает шанс получить **самоцветы более высокой редкости**.

### 2. Ролл самоцветов души
* Используйте души хаоса, чтобы получать **самоцветы души** - детали в стиле тетриса для усиления оружия.
* Каждый самоцвет души имеет:
   * **форму**
   * **уровень**  
→ **Более высокий уровень повышает эффект гравировки (верхний параметр)**, что усиливает **ATK%** оружия души.
   * **редкость**  
→ **Более высокая редкость улучшает дополнительную опцию (нижний параметр)**, которая дает бонусы, например:
`ATK, HP, восстановление HP, крит. урон, дополнительное золото, точность, уклонение`.

### 3. Размещение самоцветов души на доске гравировки
* Перетаскивайте, поворачивайте и размещайте самоцветы души, чтобы **полностью заполнить доску**.
* Полное заполнение доски дает **эффект завершения**: крупный бонус к **ATK% и HP%**.
## Рекомендации
* Отдавайте приоритет самоцветам души более высокого уровня для роста ATK% оружия души.
* Предпочитайте самоцветы высокой редкости (эпические, легендарные, мифические) для более сильных дополнительных опций.
* Старайтесь использовать как можно больше ATK-блоков (L-образных), не жертвуя полным заполнением доски.
* В ранней и средней игре золотые блоки (I-образные) могут сильно повышать ваш % золота. Поэтому полезно держать 2 набора гравировок: один для фарма золота, второй для урона.
* В поздней игре (этап 1500+) для оружия души блоки CRIT могут быть предпочтительнее из-за худшего масштабирования ATK-блоков.
### **Примечание для ранней игры: до Dragonos CRIT может временно быть сильнее ATK из-за масштабирования.**

## Советы по заполнению доски
* Всегда ставьте в приоритет полное заполнение доски, даже если нужно пожертвовать одним ATK-блоком.
* Бонус за завершение обычно дает больше, чем небольшая прибавка отдельных параметров.
* Используйте внутриигровые фильтры, чтобы:
   * фокусироваться на нужных типах параметров (например, ATK, CRIT);
   * задавать минимальную редкость (эпическая и выше), чтобы не тратить время на слабые самоцветы.
* Используйте кнопку «Change x» (удержание для быстрых роллов), чтобы перебрасывать и искать более подходящие детали.

## Рекомендации по раскладкам оружия души
Каждое оружие души имеет уникальную раскладку поля. Ниже приведен предлагаемый подход для каждого оружия, начиная с Гордыни и заканчивая последним доступным Оружием Души:
Особая благодарность Half Squirrels, Ovokano и Leoht.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/soul_weapon_engraving/image.png
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/soul_weapon_engraving/image.png
### Плоские бонусы мифической гравировки
> Примечание: это не полный бонус, который дают вам эти гравюры. Добавьте эти цифры в калькулятор Master Optimizer, чтобы определить, какую пользу вам принесет каждая гравюра.

ATK: ATK персонажа +12%
Восстановление HP: восстановление HP персонажа +12%.
Дополнительное золото: +2400%
Уклонение: +120
Здоровье: +12%
Крит. урон: Крит. урон +1200%.
Точность: +240
KR SW Wiki для поиска рекомендаций по гравировке: https://en.namu.wiki/w/%EC%8A%AC%EB%A0%88%EC%9D%B4%EC%96%B4%20%ED%82%A4%EC%9A%B0%EA%B8%B0/%EC%86%8C%EC%9A%B8%EC%9B%A8%ED%8F%B0
> Примечание: не содержит всех альтернатив для Crit vs ATK.
SW от Pride до Anxiety
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/soul_weapon_engraving/image.png
SW от Vigor и далее
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/equipment/soul_weapon_engraving/image.png
