VALUES (
  'equipment_souls_and_soul_weapons',
  'equipment',
  'Souls and Soul Weapons',
  'Информация об оружии души
**Оружие души (Soul Weapons)**
• Разблокируется на уровне 80.
• Каждые 20 этапов будут открывать новый чертеж оружия души; Зеленый, Синий и Красный.
• Стоимость создания Оружия Души увеличивается **ровно в 3×** каждые 60 этапов.

**Как получать души (How to get Souls)**
• В каждом регионе есть души, специфичные для региона. Вы можете проверить это, нажав на значок карты. Автономное фермерство вознаградит вас белыми душами, и единственный другой способ получить их — это сломать старое и необорудованное оружие душ.

• Количество душ, выпадающих из монстров, увеличивается с каждым новым регионом, который вы обрабатываете. Чем больше монстров вы убьете, тем больше душ вы получите, поэтому лучше фармить для них 18 миль в час.

• Используйте главный оптимизатор, чтобы увидеть, какой вариант следующего оружия души вам больше всего подходит, на вкладке «Фермерство». <#1092343850019868682>
