INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'equipment_weapons',
  'equipment',
  'Weapons',
  '# Информация об оружии

Существует **шесть уровней** оружия, которое можно **получить** или **объединить**:
**Обычный (Common)**
**Хороший (Great)**
**Редкий (Rare)**
