INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'event_help_event_help',
  'event-help',
  'Event help',
  'Предоставляет помощь при покупке жетонов событий, если вы не знаете, что получить.
Показ пропуска новичка после первого приключенческого квеста + атака/хп 50 ур.

Событие отображается после достижения 30-го уровня и становится доступным после 100-го уровня.
**Что мне купить в магазине событий?**
**• Духи**
1. Сначала возьмите 3 случайных эпика.
2. Терпение – это ключ! Мероприятие продлится пару недель. Так что, если вы все равно собираетесь вызывать духов в ближайшие 2 недели, наберитесь терпения и выберите легендарного духа, как только узнаете, какие еще легендарные предметы у вас есть из призыва.
3. Общие рекомендации легендарных духов можно найти в <#1120946427305152523>.

**• Карты навыков**
При работе с картами навыков обычно рекомендуется покупать редкие карты навыков.

Рекомендуемая точка остановки — все редкие пассивные умения до 20 уровня и Flame Slash до 60 или 100 уровня.
Если вы играете в онлайн-ферме, рекомендуется использовать отличные карты навыков для ловкости, чтобы улучшить скорость фарма. Если вы не становитесь ловким, вы также можете пойти на молниеносный удар. (Если вам нужны навыки более высокого уровня, лучше использовать алмазы.)

**• Билеты класса**
Более высокая ценность, чем конвертация в алмазы, но оно того стоит, только если вы работаете над повышением класса.

**• Билеты навыков**
Более высокая ценность, чем конвертация в алмазы, не рекомендуется до поздней игры, когда вы в основном конвертируете в алмазы с текущим событием.

**• Алмазы**
Не рекомендуется в начале середины игры, но это хороший вариант, если у вас закончились редкие навыки и вам не нужны перья.

**• Зеленые/фиолетовые перья**
Зеленые или фиолетовые перья могут стать отличным способом ускорить ваш прогресс. Лучше всего придержать их, если вы близки к усилению/повышению, чтобы вы могли подняться выше и получить более крупные награды.
Еще более идеальным будет сохранить их до тех пор, пока вы не обновите <:MemoryTree:1260970526642405437> и не выйдет Ancient Spirits.

**• Камни спутников**
Комп-камни обычно не являются приоритетом, если вы играете в онлайн-фермерство. Если вы не в сети или много тратите, вы можете купить их во время мероприятия, чтобы сбалансировать излишек изумрудов.

```При покупке редких карт навыков лучше выбирать пассивки/бафы, а также Flame Slash, особенно с учетом Skill Mastery после Ether.

Это все товары в магазине, которые заслуживают наибольшего внимания. Выбирайте, что вам подходит, в этом списке или вне его, поскольку каждый играет и прогрессирует по-своему. ```
-Адаптировано из гайда по тратам на ивенты, оригинал от DRG
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/event-help/event_help/eventspending_guide_updated.png
