VALUES (
  'late_game_promotions_blitz_gold',
  'late-game-promotions',
  'Blitz Gold',
  'Сборка для промо Blitz Gold :BlitzGold:

# Гайд по Blitz Gold :Blitzgold:

Гайд от Sosej.

# Духи: :Leg_sala: :Leg_radon: :Leg_loar:
Примечание: Noah здесь почти бесполезен, потому что у боя нет таймера. Проигрыш возможен только если вы умерли или сломали все навыки.

Размещение навыков очень важно.
# :SpeedSword: :EarthsWill: :skillbook: :skillbook: :skillbook:
# :CurvedBlade: :BurningSword: :skillbook: :WrathOfGods: :rave:

Зверь: ![image](assets/media/guides/late-game-promotions/blitz_gold/image.png), если его нет — используйте 🐺.

## Ключевые моменты
- Когда вы убиваете мобов, вы получаете 10 стаков :WindSword:, затем 10 стаков :IronWill:, затем снова 10 стаков :WindSword:. Намеренно добивать мобов не стоит.
- В фазе Earth каждый раз, когда вы используете атакующий навык, внутри вашего набора навыков вращается «торнадо». Оно ускоряет откат навыка или пассивки, поэтому используйте его с умом, чтобы разогнать :BurningSword: и :CurvedBlade:, особенно если играете через Draco.
- При переходе в фазу Wind все навыки вокруг «торнадо» ломаются. Сломанные навыки не вернутся, поэтому планируйте вращение заранее.

## Советы
:roeycheck: Первая «половина HP» на самом деле является щитом. Из-за этого Sala очень сильна, потому что «HP босса» не уменьшается, а урон всегда идет как 10% от HP. || не говорите мне, что у вас до сих пор нет прокачанной Sala :ahoecat: ||
:roeycheck: Чтобы играть через Draco, нужно строго соблюдать расстановку навыков и использовать CD water stone. Иначе вы не успеете набрать все пассивки.

Возможно, есть и другие нюансы, но мне пока лень :worrychill:

Примеры прохождения:
![blitzgod](assets/media/guides/late-game-promotions/blitz_gold/blitzgod.mp4)
![image](assets/media/guides/late-game-promotions/blitz_gold/image.png)

# :Blitzgold: Blitz Gold - Guide to and Mechanic Breadown
Рекомендуемый этап: 1670 ±5

**У босса 3 фазы**

🗿 **Statues** -
Каждая статуя, убитая до появления босса, дает постоянный бафф до конца боя. (Atk/Attack speed)
Статуи считаются мобами и на них действуют :Radon:, :Imm_mum:, :Zappy: и :Kart:.

🌏 **Earth** -
Босс ставит песчаную метку на один из ваших навыков. Метка не дает использовать этот навык. Если использовать активный атакующий навык, метка начнет двигаться по часовой стрелке по сетке навыков и временно заморозит все, на что попадет. Перед переходом в Wind босс заряжает мощную атаку, которую показывает желтая шкала.

:BlastWind: **Wind** -
Когда босс переходит из Earth в Wind, область 3x2 вокруг песчаной метки получает урон и отключается до конца боя. Максимум можно выдержать 3 таких попадания, после чего все навыки отключаются и бой заканчивается. Босс будет периодически чередовать Wind и Earth.

:skillbook: **Skills** -
Расстановка навыков очень важна. Раскладывайте их слева направо или справа налево так, чтобы босс сначала ломал пассивки, а Rave оставался последним.

*Spirits*:
:Imm_noah: не работает, потому что у босса нет таймера.
Рекомендуемые духи: :Loar:, :ancientSalamander:, :Radon:.
Если :Radon: не прокачан, используйте :Mum:, :Zappy: или духа с самым высоким атакующим статом.
Последний Rave используйте, чтобы записать Fam+Sala. Держите его до конца боя, чтобы выжать больше урона от Sala.

*Beasts*:
:dragon: Рекомендуются звери Draco.

Гайд от Carnage; правки от Ban.
