VALUES (
  'late_game_promotions_diadust',
  'late-game-promotions',
  'Diadust',
  'Сборка для продвижения Diadust <:Diadust:1365046130702024825>
# <:Diadust:1365046130702024825> DiaDust - гайд и разбор механик
stage = 1490 ~ 1500, зависит от того, есть ли у вас JE<:Fam_JE:1319159000863866890>
Предупреждение: читайте внимательно, иначе вам придется МЕГА ТЯЖЕЛО бороться с ней.

## Ультимейт босса (Boss Ultimate)
Босс будет собирать синего призрака каждый раз, когда вы применяете к нему атакующий **навык**.
(синий шар вокруг босса)
Как только она соберет 7 призраков, она сначала зарядится, а затем использует свой ульт, подбросит вас и разрежет на миллион кусочков<a:worryparry:1078109040225292338>

Есть два этапа борьбы
## **1-я фаза - Still Water <:Meditation:1054837527204352010>** (100x -> 75x)
На этом этапе босс не будет контратаковать. Она бы просто стояла на месте.
В этой форме она до сих пор собирает призраков

## **2-я фаза - Rampage Blizzard <:Blizzard:1054837537312608287>** (75x -> 0x)
Босс сначала отбросит вас БОЛЬШИМ уроном (вы можете увернуться) и перейдет в режим парирования.
с каждым ударом обычная атака или умение будет отражать вам фиксированный урон.
Как только она наберет одновременно 50x и 25x HP, она будет использовать «Her Rave» — собирая урон, который вы ей наносите, и накладывая его обратно вам.

На этом этапе все непассивные персонажи начнут обледенеть, как только будут готовы.

Важно: при нормальных обстоятельствах здоровье босса НЕ упадет ниже 1x, он покажет свое слабое место только **во время зарядки своего ультимейта.**
Если вы воспользуетесь шансом и нападете на нее **во время зарядки** и уменьшите ее здоровье до 1x, она оттолкнет вас назад и начнет собирать ледяную силу. Тем временем время застыло, и вам нужно разбить и обледеневшее хп, и последнюю полоску 1x.

## **Разбор механики**:aworryBrikThrow: 
**1.**
Способ, которым босс собирает призрака, зависит от количества использованных вами атакующих навыков. Используйте это правило на первой фазе и соберите достаточно призраков, которые вам нужны на последний момент (необходимо 7 призраков).
Кроме того, фам и сала не считаются «навыком атаки», а только теми, которые входят в ваш набор навыков.

Примечание: Рейв (запись) не считается навыком атаки, засчитывается только Рейв (высвобождение).

**2.**
На 2-й фазе отраженный урон наносится при попадании, то есть ваша обычная атака отражается один раз, DH отражается 7 раз, aFS отражается дважды и т. д.
Если у вас низкий уровень здоровья и регенерации, вы можете использовать сборку без скорости атаки, как у меня.

Для моего требования к сборке:
ДМГ - достаточно<:worryroey:1090019626307555329>
ХП - не имеет значения
**Реген - должен быть выше 4K (4e33)**
Руководство создано <@354547215169093632>
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/late-game-promotions/diadust/DiaDust.mp4
## Кратко (TL;DR)
Каждое активное атакующее умение, которое вы используете (включая освобождение рейва), дает ей синюю душу, и при 1x HP она будет уклоняться от любого урона, если только вокруг нее нет 7 синих душ (заряжается ее ульта).
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/late-game-promotions/diadust/image.png
Примечание. Ледяная полоса в конце боя имеет здоровье примерно в 13 раз. Таким образом, после нанесения 99-кратного урона для срабатывания ледяного здоровья, необходимо нанести 14-кратный урон, чтобы завершить бой.
сборка fs с синим волком, dw или изогнутая, в зависимости от уровня сферы
<:EarthsWill:1054837582124560485> <:SpeedSword:1054837558133129236> <:WrathOfGods:1054837540970057778> ( <:CurvedBlade:1054837628563890197> / <:DancingWave:1054837660025360464> ) <:Rage:1054837629679575160>
<:rave:1055598059628789772> <:Meditation:1054837527204352010> <:BurningSword:1054837580388126721> <:FlameSlash:1054837335084236881> ( <:WarriorBurn:1054837661195583558> / <:LightningBody:1054837662445469706> )
Партнер Ноя / Лоар / Сала
Уложите зверя до 3
Меди прямо перед вогом
Подожди, пока вог поднимется
начать рейвить
Наносите удары до тех пор, пока количество зверей не достигнет 9.
ДВ
Подожди 75 раз
Выпустите Rave > medi > снова взорвитесь до зверя 14.
Подождите, пока в конце появится бредовое комбо, убедитесь, что вы довели ее до х50, прежде чем использовать знакомый

