Волк

Стратегия: максимизируйте ярость, рассчитывая время вручную, используйте, когда активен плавный клинок / волк, если здоровье не является проблемой, вы можете автоматически яриться.
Уничтожение вога для третьей атаки может быть хорошим вариантом, поскольку время простоя может привести к потере урона в секунду во время боя. Это также может помочь вам пройти через больше мобов в начале, что приведет к увеличению времени таймера и облегчению фаз босса.

Совет: отключите авто перед тем, как вступить в бой, чтобы не тратить зря время работы навыков.
Пример видео:
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/late-game-promotions/eisenhart/raveless_eisen_win.mp4
