У меня также 11* Orb, Max Rave, Max Every Passive Skill.
Этот бой требует времени и практики. Босс — Ветер, поэтому Земля очень сильна (ОП).
Лучший знакомый: ТИШАНА
Хорошая возможность часто рейвить.
У босса медленные атаки, несколько жизней и вначале он призывает миньонов (Руки/Врата), чтобы продлить таймер.
⚠️ Возможна очистка без ЭДГ.
Храм Дракона: Уровень 4
Ссылка: Carnage Video (шаблон), Vacation/Adda (руководство)

***Фаза 1 - Руки/Врата***

Очистите 3 набора рук/ворот и 2 руки, чтобы получить достаточно дополнительного времени.

***Фаза 2 - Босс (4 жизни = 4 черепа)***

1-я жизнь:

Тщательно рассчитывайте время для WB, WOG и Rave.

Своевременный Рейв должен уничтожить первую жизнь.

Когда босс оживает, он вызывает отбрасывание и замедляет способности, основанные на времени. Размещение и порядок способностей имеют решающее значение.

2-я жизнь:

Сгорите быстро.

При необходимости используйте Rave.

Третья жизнь:

Если вы правильно рассчитали время, вы на финишной прямой.

Настройте ротацию: WoG → WB → Rave/Noah.

Вставьте своего Familiar, затем DH внутри Rave.

Комбинация Fam + DH должна положить конец этой жизни.

4-я жизнь:

Осталось всего несколько секунд.

Используйте Рейв, чтобы закончить бой.
