***Гайд от нашего любимого клоуна***

Дух: Лоар (главный), Сала, Ной.
СМ: A2GS, A2RL, EDH
Семья: 10* ХИКУНА

**Фаза ветра (Wind Phase)**
Запустите Rave, когда таймер WOG достигнет ~8 секунд, чтобы записать и выдохнуть первое сала-вдох.
Сохраняйте DH до тех пор, пока вог не сделает двойной DH с помощью Med. Сала сработает между ними, поэтому оставьте второй DH для после дыхания.
Опустите босса примерно до 30 бар и выключите авто. (Это необходимо для того, чтобы у Рейва было достаточно урона, чтобы уничтожить босса в фазе огня)
Ной сработает после отбрасывания босса. Используйте мед, чтобы вызвать рейв и вог и зарядить рейв. У вас есть только короткое время, чтобы заставить босса сменить фазу перед срабатыванием Салы.

**Фаза огня (Fire Phase)**
После завершения смены фазы снова включите автоматический режим. Если ветер был сделан правильно, у вас все равно должно быть дыхание Ноя, Вога, Рейва и Салы. Вы все еще можете втиснуть еще один DH до истечения срока действия. Рейв пока не выпускайте.
Нанесите урон боссу, как обычно, и подождите, пока босс активирует среднюю колонку навыков. Релиз Рейв и мед. (вы можете позволить навыку гореть некоторое время, прежде чем выпустить рейв, чтобы вы могли войти в воду с Вогом прямо, но Сала может сработать между ними, поэтому проверьте это самостоятельно)

**Фаза воды (Water Phase)**
Просто атакуйте как обычно и как Мед, когда он активен.
Вам нужно затянуть эту битву, чтобы лекарство почти исчезло. Если вы наносите слишком много урона, вы перейдете в фазу Земли слишком рано, прежде чем выйдут Рейв и Вог. Выключите авто и вручную некоторые навыки, если это необходимо.
Вам нужно перевести его в фазу Земли сразу после того, как он заморозит ваш предпоследний навык. Если уже слишком поздно, Сала сработает на этой фазе.
Выкл. авто.

**Фаза земли (Earth Phase)**
Когда босс переходит на Землю, Мед поднимает Рейва и Вога.
Сначала позвольте сала-дыханию сработать перед DH, затем включите авто.
Вы можете использовать заморозку времени от DH и Fam, чтобы позволить RL наносить больше урона.
Освободите Рейв.
