Мы стремимся к Рейву только дважды. Один раз сразу после фазового сдвига, один раз в конце для Вога+Ноя+Фамильяра.

<:RedLightning:1054837517523882115> — ключевой навык для устранения щитов.

Время для фазы 2 зависит от того, когда вы пройдете фазу 1, по моему мнению, победа над ним сразу после первого срабатывания вога была идеальной. Для этого я отключаю Auto и нажимаю <:FlameSlash:1054837335084236881> сразу после срабатывания <:WrathOfGods:1054837540970057778>.

