Сала должен быть вашим главным партнером.
Этот босс требует **выбора времени и практики.**
Босс - Огненный Босс. Навык воды был бы великолепен, но большинство из них — мусор, если мы не говорим об определенном событии по навыкам воды.
Требуется 3 рейва.
Босс обладает эффектом горения, поэтому необходимо размещать навыки в правильном порядке.
Основные способности - это КБ и переворачивайте свои навыки из разных рядов.

С моей сборкой; вот как это работает.
Нажмите <:Blizzard:1054837537312608287>, затем <:Meditation:1054837527204352010>.
Подождите, пока ваш <:WrathOfGods:1054837540970057778> не станет компакт-диском 8.2-8.6, затем <:rave:1055598059628789772>.
Босс отбросит вас назад; как только вы вернетесь, <:Sala:1129588010032308294> должен появиться в <:rave:1055598059628789772>.

Здоровье босса должно быть около 769x.

<:rave:1055598059628789772> вскоре после этого; затем <:Blizzard:1054837537312608287>
Сохраните <:Meditation:1054837527204352010> до тех пор, пока не появится <:WrathOfGods:1054837540970057778>.
<:Blizzard:1054837537312608287> Во время зарядки Босса (желтая полоса); это даст вашему <:Meditation:1054837527204352010> некоторое время на восстановление.
Нажмите <:Meditation:1054837527204352010> + <:rave:1055598059628789772>, как только вы станете КБ. Pop Rave, как только он будет готов; Должен иметь способности Сала.

HP босса должно быть около 400x или ниже.

<:Blizzard:1054837537312608287> Во время зарядки Босса (желтая полоса); это даст вашему <:Meditation:1054837527204352010> некоторое время на восстановление.

После отбрасывания; вы должны нажать <:Meditation:1054837527204352010> в нужное время, иначе ваш Rave/Wog сбросится до 0 CD. Время, когда ваше лекарство загорится, будет соответствовать вашим навыкам; вытолкните его после того, как он попадет в верхний левый угол значка.

Если у вас правильное время; ты почти там. Подождите, пока Мед будет готов; лопни это. Rave + Familar + Blizz (при необходимости).

Босс должен быть ниже 125x, когда на него ругаются. потом ГГ.
Если вы не умеете поп-рейв; тогда ваше время вышло.

