INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'mid_game_promotions_cyclos',
  'mid-game-promotions',
  'Cyclos',
  'Продвижение сборки для Cyclos<:Cyclos:1209706860727242823>
Битва начинается с 1 статуи, 2 статуй, 3 статуй и затем 4 статуй перед боссом. Каждый раз, когда вы убиваете статую, перезарядка вашего навыка будет ускоряться сверху слева направо и снизу слева направо, поэтому правильное расположение навыков важно в этой битве.

В фазе босса босс будет совершать заряженную атаку, и каждый удар будет снимать эффект ускорения восстановления в том же порядке. После того, как уровень босса достигнет ровно 50% (вы не можете превысить этот порог), он снова отправит вас обратно в фазу статуи, где убийство статуи не дает ничего, кроме как добраться до босса и убить его.
<:CurvedBlade:1054837628563890197> <:BurningSword:1054837580388126721> <a:Pepehairspin:1211212441988366367> <a:Pepehairspin:1211212441988366367> <:StrongCurrent:1054837556778373120>
<:WrafofGod:1054837540970057778> <:Rage:1054837629679575160> <a:Pepehairspin:1211212441988366367> <:Meditation:1054837527204352010> <:rave:1055598059628789772>
<a:Pepehairspin:1211212441988366367> обозначает навык атаки или усиление, которое вы хотите использовать. Каждая учетная запись отличается друг от друга, поэтому выбирайте свои собственные навыки атаки и/или усиления. Вы можете использовать 3 атаки или 2 атаки и 1 бафф.
Для духа вы можете использовать другой вариант. Просто попробуйте сами, какой вариант подойдет вам лучше всего.
<:ImmortalBull:1195951217524867154> <:ImmortalLoarV2:1195951234327257138> <:ImmortalSalav2:1195951394973302814>
<:ImmortalLoarV2:1195951234327257138> <:ImmortalSalav2:1195951394973302814> <:ImmortalMumv2:1195949656354586744>
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@gh-pages/assets/images/slayerpedia/video/3x-dh-in-rave-this-is-meant-for-late-game-bossing-0.mp4
