INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'mid_game_promotions_demon_metal',
  'mid-game-promotions',
  'Demon Metal',
  'Акция "Сборка для Demon Metal" <:demonmetal:1060039752704864336>
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/mid-game-promotions/demon_metal/Demon-unscreen.gif
**Информация о битве продвижения**
В этой акции 100 миньонов с боссом, у которого высасывается жизнь.
Мобы исчезнут по таймеру, или вы убьете максимум 70 миньонов. Босс появится с полосками здоровья, соответствующими количеству оставшихся в живых мобов.
Например, 70 миньонов все еще живы, и босс появится с полосками 70 единиц здоровья.

Рекомендация по сцене: 550
Навыки

<:SpeedSword:1054837558133129236> <:EarthsWill:1054837582124560485> <:CurvedBlade:1054837628563890197> <:BurningSword:1054837580388126721> <:Meditation:1054837527204352010>
<:WrathOfGods:1054837540970057778><:FlameSlash:1054837335084236881> (<:HellfireSlash:1054837443347615796>/<:Blizzard:1054837537312608287>/<:GigaImpact:1054837516102021211> /<:FlowingBlade:1054837613074321561>/<:Rage:1054837629679575160>/<:rave:1055598059628789772>/ <:DemonHunt:1054837525799248034>)

<:Leg_noah:1060758788237443132> Духи
<:Leg_noah:1060758788237443132> <:Leg_loar:1060758780775764058> <:Leg_sala:1060758775839080598>

<:guide:1055587557976580106> Советы
При выталкивании первого <:rave:1055598059628789772> рассылайте спам <:rave:1055598059628789772>, чтобы получить <:Leg_sala:1060758775839080598> в открытии, если не получится, перезапустите
Чем больше миньонов вы убьете, тем легче будет бой.
В конце концов очень сложно получить 2x <:DemonHunt:1054837525799248034> внутри <:rave:1055598059628789772>, попробуйте запланировать это так, чтобы активировать <:Meditation:1054837527204352010> и <:rave:1055598059628789772> в 23.5-21. Остался таймер <:WrathOfGods:1054837540970057778>, дождитесь появления <:Leg_noah:1060758788237443132>, спамьте двойной <:DemonHunt:1054837525799248034>, а также спамьте <:rave:1055598059628789772> в самом конце.

Совет по механике боссов
У босса есть навык «Похищение жизни». После появления босса сохраните оглушение и примените его только для того, чтобы сломать навык босса. Используйте оглушение, как только босс применит «истощение жизни» (не используйте оглушение, пока заряжается желтая полоса, так как это не сработает).
