**Информация о битве продвижения** 
9 мобов нужно убить до появления Босса. Босс может сбросить время восстановления навыков в первом, а затем во втором ряду, помните о размещении навыков.

**Минимальное** снаряжение для промо-класса Драконос.

<:dragonatk:1290963101914628137> **Статистика**
**Рекомендованный этап: 610**

**Билды навыков**

<:HellfireSlash:1054837443347615796><:FlowingBlade:1054837613074321561><:WrafofGod:1054837540970057778><:Meditation:1054837527204352010><:Rage:1054837629679575160>
<:FlameSlash:1054837335084236881><:SpeedSword:1054837558133129236><:EarthsWill:1054837582124560485><:CurvedBlade:1054837628563890197><:BurningSword:1054837580388126721>

<:HellfireSlash:1054837443347615796><:FlowingBlade:1054837613074321561><:WrafofGod:1054837540970057778><:Meditation:1054837527204352010><:rave:1055598059628789772>
<:FlameSlash:1054837335084236881><:SpeedSword:1054837558133129236><:EarthsWill:1054837582124560485><:CurvedBlade:1054837628563890197><:BurningSword:1054837580388126721>

<:DemonHunt:1054837525799248034><:WrafofGod:1054837540970057778><:rave:1055598059628789772><:Meditation:1054837527204352010><:Blizzard:1054837537312608287>/<:GigaImpact:1054837516102021211>
<:FlameSlash:1054837335084236881><:SpeedSword:1054837558133129236><:EarthsWill:1054837582124560485><:CurvedBlade:1054837628563890197><:BurningSword:1054837580388126721>

<:noah:1060758788237443132> **Духи**
<:noah:1060758788237443132> <:loar:1060758780775764058> <:sala:1060758775839080598> <:mum:1060758787092402237><:zappy:1060758779488112701>

**Совет по механике босса**
У Босса есть 2 способности;
1-й - Сброс CD. Сбросьте свой КД в 1-м ряду навыков, а затем во 2-м ряду навыков.
Это значит, что порядок развития навыков очень важен.
Попробуйте сработать <:Meditation:1054837527204352010> прямо перед тем, как его способность достигнет 5-го слота навыков.

2 место - АС Бафф. Он увеличит скорость атаки;
вам необходимо <:Blizzard:1054837537312608287>/<:GigaImpact:1054837516102021211> или большое количество здоровья, чтобы противостоять этому.
