Навыки Инфинаута:

<:FlameSlash:1054837335084236881>(<:HellfireSlash:1054837443347615796>/<:RedLightning:1054837517523882115>)(<:Blizzard:1054837537312608287>/<:LifeMana:1054837659052285972>)<:FlowingBlade:1054837613074321561><:Meditation:1054837527204352010>
<:WrafofGod:1054837540970057778><:CurvedBlade:1054837628563890197><:SpeedSword:1054837558133129236><:BurningSword:1054837580388126721><:EarthsWill:1054837582124560485>

<:FlameSlash:1054837335084236881>(<:HellfireSlash:1054837443347615796>/<:RedLightning:1054837517523882115>)<:FlowingBlade:1054837613074321561><:rave:1055598059628789772><:Meditation:1054837527204352010>
<:WrafofGod:1054837540970057778><:CurvedBlade:1054837628563890197><:SpeedSword:1054837558133129236><:BurningSword:1054837580388126721><:EarthsWill:1054837582124560485> (Если вы можете убить фазу 2 во время рейва, чтобы мгновенно убить фазу 3 с помощью рейва)

