Информация о промо-битве
Босс продолжает менять фазы, и каждый раз, когда цвет меняется с СЕРОГО на КРАСНЫЙ, 3 навыка будут мигать красным и блокироваться на несколько секунд. На красной полосе он имеет сопротивление урону, поэтому не используйте DH или Rave на этой фазе. На сером баре у него нет сопротивления, самое время для больших бонков!

Рекомендация по сцене: 700

Порядок построения навыков
<:Blizzard:1054837537312608287> <:WrafofGod:1054837540970057778> <:DemonHunt:1054837525799248034> <:CurvedBlade:1054837628563890197> <:SpeedSword:1054837558133129236>
<:BurningSword:1054837580388126721> <:EarthsWill:1054837582124560485> <:Meditation:1054837527204352010> <:FlameSlash:1054837335084236881> <:rave:1055598059628789772>

<:guide:1055587557976580106> Советы
Время очень строгое, поэтому обратите внимание на ротацию и особенно на то, когда использовать <:Meditation:1054837527204352010>.

Совет по механике боссов
Фазовый сдвиг. Он увеличит свое сопротивление и заблокирует 3 умения игрока;
вы должны <:Blizzard:1054837537312608287> остановить его и заблокировать ваши навыки.
