VALUES (
  'promotion_recommendation_promotion_recommendation',
  'promotion-recommendation',
  'Promotion recommendation',
  '## Краткий справочник: этапы развития игры

**Ранняя игра** – *Начало игры → Разблокировка мастерства навыков*
Вы только начинаете изучать элементальный урон.
Прогресс происходит быстро, с частыми обновлениями и небольшим количеством узких мест.

**Середина игры** – *Разблокировка `aFS` → Класс до Seed*
На этом этапе разблокировано большинство основных механик и систем.

**Поздняя игра** – *Достижение прорыва 2 на дереве памяти → разблокировка `a2HFS` / `a2TBS`*
Большинство «простых» обновлений уже сделано.
Теперь игра смещается в сторону ограниченного по времени развития и долгосрочного фарма.

**Конец игры** – *максимальные навыки, получение опыта, трата зеленых перьев*
Вот и все, больше не от чего получать обновления

> **Примечание.** Эти этапы могут меняться по мере добавления в игру новых обновлений или контента.
> **Примечание.** Предлагаемые значения «Попробовать» основаны на прогрессе этапа, а не на статистике, даже если на связанных страницах сборки отображаются рекомендации по статистике.

> **Примечание.** Некоторые ссылки могут отображаться как «неизвестные», но они все равно будут направлять вас к правильному руководству по созданию продвижения.

