VALUES (
  'shop_shop',
  'shop',
  'Shop',
  'https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/shop/shop/Goods_AllScroll.png
# Система жалости при призыве оружия и аксессуаров
В этой игре система призыва включает в себя механику жалости, которая гарантирует определенные награды после достижения определенных этапов.

# Уровни призыва и награды жалости
* Чем больше призывов вы делаете, тем выше ваш уровень призыва, что повышает шанс получить снаряжение более высокого качества.
* На определенных этапах жалости вы гарантированно получаете награды, как показано ниже:
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/shop/shop/image.png
# Дополнительные механики
* **Редкость снаряжения (Gear Rarity):** экипировка из summon имеет следующую редкость:
`Мифик > Легендарный > Эпический > Редкий > Отличный > Обычный`
* У каждого тира редкости есть **grade** от **G4** (самый низкий) до **G1** (самый высокий). Например, **"M1"** означает **Mythic Grade 1** - это лучшая экипировка, которую можно получить из summon.
* Начиная с **уровня призыва 8**, за каждые **10,000 призывов** игрок получает 1x M1 (Mythic G1).

-# By <@328291946739269633>
**Магазин (Shop)**

*Призыв* 
- При призыве оружия или аксессуаров, достигнув определенного уровня призыва, не забывайте забирать награду жалости.
- Чем выше уровень призыва, тем выше вероятность получить лучшее снаряжение.
- После достижения уровня призыва 8 каждые 10k призывов дают 1x M1.
- Призыв карт навыков обычно невыгоден, если вы не донатер или не в поздней игре.

*Рекламный призыв*
- После каждого сброса забирайте 3x рекламного призыва для оружия, аксессуаров и карт навыков.

*Пакеты*
- **Ваши деньги - ваш выбор.**
**Не чувствуйте себя обязанными донатить: в игру можно играть как F2P, просто прогресс будет медленнее. Это рекомендации по максимальной ценности для тех, кто готов тратить.**
- Лучшие варианты - пакет без рекламы и Newbie Slayer Pass.
- Newbie Pass - один из самых выгодных пакетов в игре. Вы получаете Mythic Grade 1 Weapon (M1); для сравнения, 1 M1 обычно стоит около 450k алмазов (примерно $350).
- Stage packs тоже очень выгодны по соотношению ресурсы/стоимость.

*Ивент*
- Открывается только в период события.
- Обычно дает очень высокую ценность по ресурсам.
- Event Pass чаще выгоднее stage packs.
- Skill event pass менее выгоден.
- Event packs чаще подходят для крупных донатеров.
- Иногда доступны ограниченные пакеты на 48 часов; их ценность разная, но часто они выгоднее обычных stage/event packs.

Приоритет стоимости расходов:
Newbie Slayer Pass > Без рекламы > Event Pass > Ограниченные по времени пакеты > Skill Event Pass > Event Packs > Stage Pack

*Товары*
- Забирайте бесплатные 10x Diamond/Emerald.
- Обменивайте 10k Dices на 1k Emeralds.
- Не обменивайте feathers/diamonds.
- Обмен Elemental Stone на 3k Emeralds имеет смысл начиная с <:adamant:1054852905020170390>.

*Золотой ключ*
- Всегда сохраняйте ключи для Hunter Support Chest.
- Алмазы через ключи имеет смысл добирать только при высоком донате и закрытии лимитов.
