INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'skills_familiars',
  'skills',
  'Familiars',
  'Информация о фамильярах (/лошадях)
# Фамильяры (Familiar)
Разблокировка после Demon Metal <:demonmetal:1060039752704864336>

Это приблизительные рекомендации: генерация мрамора души влияет на вашу способность эффективно улучшать фамильяров. Именно тогда будет реалистично стремиться к этим пробуждениям.
<:demonmetal:1060039752704864336>-<:DarkNox:1139514468557140089>: Алтарь 38+/Уровень знакомого 6–7*
<:BlueAbyss:1141496057423999026>-<:Cyclos:1209706860727242823>: Алтарь 47+/Уровень знакомого 8*
<:AncientCanine:1257278191832399872>: Алтарь 50+/Уровень знакомого 9*
<:Gigarok:1283966815814291456>: Алтарь 53+/Уровень знакомого 10*

## Категории

Есть три категории фамильяров, в каждой категории есть 4 разных типа фамильяров со своими уникальными активными навыками.

**Примечание:** все бонусы фамильяров, кроме mana altar, являются активными, а не пассивными.

**Категория 1 - Элемент (Element)**
Это обеспечивает повышение определенного элемента навыков. Урон **(X%)** увеличивается в зависимости от звезды фамильяра.
**TI** - земля (earth)
**HI** - огонь (fire)
**A** - вода (water)
**JE** - ветер (wind)

**Категория 2 - Метод атаки (Attack Method)**
Это определяет метод и частоту атаки в зависимости от звезды/ранга фамильяра.

**KU** - атакует врага ***X*** ударами (останавливает таймер как DH)

**PO** - атакует врага ***X*** ударами через 2 секунды после начала боя (пауза таймера)

**SHA** - случайно атакует ***X*** раз в пределах дальности (есть анимация каста, в этот момент вы ничего не делаете; таймер НЕ останавливается)

**PE** - атакует 1 раз в секунду в течение ***X*** секунд (во время анимации каста таймер на паузе; **после стартовой анимации таймер снова идет**)

**Категория 3 - Дальность (Range)**
Эта категория определяет дальность действия навыка фамильяра с дополнительным множителем урона. ***X*** по мотивам звезды знакомого.

**NA** - наносит ***X***% урона с **1** дальностью (по сути первая цель автоатаки).

**MUS** - наносит ***X%*** урона с ***X*** дальностью.

**RU** - наносит ***X%*** урона с **X** дальностью.

**RION** - наносит ***X%*** урона с **X** дальностью.
## Расчет урона

урон от знакомых навыков **всего**= https://discordapp.com/channels/1052865879609724968/1125716822612787261/1234331386178048104 (часть урона от навыков находится в последней части, как и другие навыки)

поскольку он работает так же, как и другие навыки, все пассивные характеристики атаки (EW, WOG, Noah, Loar, Mum и т. д.) также будут работать на знакомом навыке. Кроме того, его еще можно записать в Rave.
 **Можно использовать только ОДИН раз за бой**

урон от знакомых навыков (**отношения трех разных категорий**) =
(Категория один%) * (Категория два удара) * (Категория три X% урона)

обратите внимание, что сама дальность не влияет напрямую на урон, а влияют только фактические попадания из второй категории.

Например, 6-звездочный MUS с PE будет атаковать каждую секунду на расстоянии 16, но урон от каждого удара одинаков для дракона и одного крошечного босса уровня.
## Комбинирование

Фамильяра можно комбинировать тем же дубликатом или любым фамильяром той же редкости И той же категории для перехода на более высокий tier. У дубликатов шанс успеха в 2 раза выше. Шанс успеха складывается, поэтому можно доводить его до 100% несколькими материалами. Для примера: дубликат 0⭐ дает 100% успеха, а 5⭐ - 50%.

При комбинировании в 6⭐ и выше потребуются Soul Marbles (см. ***https://discord.com/channels/1052865879609724968/1299025902595997726/1299348361622847528***).


**Пакетное объединение (Batch Combine)**

Разблокируется после достижения **уровня жалости 1**.
https://discord.com/channels/1052865879609724968/1052865880016568406/1299397605557796864

Как только он будет разблокирован, он будет использовать только дубликаты указанных вами фамильяров, чтобы достичь 100% успеха при объединении.
**Перевод в игре некорректный: функция не использует материалы, которые НЕ являются дубликатами выбранного фамильяра.**


## Алтарь маны (Mana Altar)

Этот раздел появится, когда у ваших **шести** лучших фамильяров в общей сложности будет 30⭐. Это даст вам либо % урона от навыков, либо процент производства мрамора души (<-- см. ***Святилище души***) и любые дополнительные ⭐, которые вы получите за свои шесть лучших, начиная с 30⭐.

**Примечание:** если у вас два дубликата 6⭐ или выше, в mana altar будет учитываться только один. Система не допускает дубли одного и того же фамильяра.

Бафф% урона навыка, который вы получаете от изменения маны, является независимым множителем.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/skills/familiars/IMG_0678.png
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/skills/familiars/IMG_0679.png
## Святилище душ (Soul Sanctuary)

Эта функция **разблокируется** после того, как вы достигнете хотя бы одного 6 ⭐ знакомого.

Слот для сбора шариков души будет разблокирован в зависимости от ваших пройденных промоакций. В каждом слоте будут разные настройки времени, необходимого для сбора души. В каждом слоте также есть «бонусный фамильяр»**. Их использование увеличит количество собираемых шариков души и максимальное хранилище на 50%.

Чем выше ⭐ назначенного вам фамильяра, тем выше скорость и максимальный объем памяти (для выращенных шариков души).
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/skills/familiars/IMG_0677.png
**Важное примечание**
X/X% относится к значению/баффу, предоставляемому фамильяром до тех пор, пока предоставленная статистика не будет должным образом раскрыта. На данный момент оно останется пустым, поскольку эта статистика не является постоянной и будет меняться по мере дальнейшего улучшения ваших фамильяров.

Для боев вы должны указать, хотите ли вы, чтобы ваш фамильяр активировался автоматически или вручную. Для большинства боев рекомендуется использовать ручной режим, особенно для битв с боссами, использующих рейв, чтобы максимизировать потенциальный наносимый урон.

**PO** имеет фиксированный таймер активации атаки, поэтому всегда будет работать автоматически.

Чтобы настроить автоматическое включение/выключение фамильяра, вы можете либо нажать в настройках боя, либо выключить его через основного фамильяра.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/skills/familiars/IMG_0684.png
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/skills/familiars/IMG_0683.png
**Возможные комбинации**
Для боев с применением рейва настоятельно рекомендуется использовать |BLANK| КУ НА. KU может приостанавливать таймер на всю продолжительность своей атаки, не отнимая времени на активацию ваших собственных навыков, а NA имеет максимально возможный урон с наименьшей дальностью, это абсолютно лучший вариант для боя с боссом 1 на 1.
Другие боевые фамильяры могут нанести больший урон, чем КУ одновременно ⭐, но, как уже говорилось, его способность полностью приостанавливать таймер чрезвычайно сильна для восторженных пользователей.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/skills/familiars/image.png
