INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'skills_immortal_skills',
  'skills',
  'Immortal Skills',
  'Информация о бессмертных навыках. <:rave:1055598059628789772> <:Mantra:1054837329367420998>
Существует только **два** навыка уровня Бессмертных: **Рейв** и **Мантра**.
Эти навыки можно приобрести только тогда, когда вы получите их последующее снаряжение уровня «Бессмертный».
• Для Рейва требуется **Меч Света — Орр**.
• Для мантры требуется **Сфера надежды**.

**Rave** <:rave:1055598059628789772>
«Нанести дополнительный урон в размере 70% от урона, нанесенного одному врагу, в течение 5 секунд».
Может быть улучшен до **Rave V (110%)**, при этом каждое улучшение дает дополнительные 10% за уровень и стоит 1 мифический уровень 1. Рекомендуется избегать повышения уровня этого навыка до тех пор, пока вы не закончите **Максимальное пробуждение Орра.**

**Mantra** <:Mantra:1054837329367420998>
«Общая атака, здоровье +30%» Это увеличение характеристик применяется без установки слота навыка.
Может быть улучшено до **Мантры V (70%)**, при этом каждое улучшение дает дополнительные 10% за уровень, стоимость 1 мифического уровня 1. Рекомендуется **Максимально увеличить мантру** перед разблокировкой ожога воина.
