INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'skills_skill_building',
  'skills',
  'Skill Building',
  '# Здание навыков 101
#                     ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ ─ .
- Комбинируйте пассивные навыки, положительные эффекты и навыки атаки, чтобы максимизировать эффективность. Обычно вам не понадобится более 3-4 атакующих навыков в одном билде, часто склоняясь к 1 или 2.
- Подумайте, как взаимодействуют время восстановления и время ваших навыков. <:Meditation:1054837527204352010> Медитация необходима для управления временем восстановления, чтобы навыки были активными или готовыми в течение желаемых окон.
- Подумайте о синергии между навыками. Например, <:WrafofGod:1054837540970057778> Гнев Божий, <:StrongCurrent:1054837556778373120> Сильный ток, <:LightningBody:1054837662445469706> Тело молнии, <:WarriorBurn:1054837661195583558> Warrior Burn и <:rave:1055598059628789772> Rave имеют период активности ~5 секунд. Если все они активированы одновременно, они могут создать окно для нанесения огромного взрывного урона.
- Выберите навыки, которые помогут вам достичь вашей цели в сценарии. Если вам нужно убить много мобов, выбирайте навыки с большой дальностью поражения, чтобы поразить как можно больше мобов. Если вам нужно убить одного босса, выбирайте умения ближнего действия, которые наносят больше урона цели.
# ─────────────── Навыки ────────────────
# <:Медитация:1054837527204352010> Медитация (Меди)
Наверное, самый ценный навык в этой игре.
- Меди — единственный навык, который дает пользователям активный контроль над временем восстановления, что делает его основным требованием почти для каждой ротации навыков в игре.
- В фарме это позволяет вам фармить быстрее, сохраняя бафф <:Agile:1054837638730879106> Agile (а также другие баффы) и уменьшая время восстановления <:Susonic:1054837538793197628> SS.
- Помимо фарма, он обычно используется вручную для определения времени активации важных навыков, таких как <:WrafofGod:1054837540970057778> WoG, которыми иначе нельзя управлять.
- Хотя есть некоторые нишевые сценарии, в которых этот навык не будет использоваться, эти случаи являются редкими исключениями. Если сомневаетесь, включите <:Meditation:1054837527204352010> Medi.
# ────────── 📈 Пассивные пассивы ──────────
-# Навыки без длительности, активны до конца боя
# <:SpeedSword:1054837558133129236> Скоростной меч (SS)
- Незаменим в начальстве. Будучи пассивным умением с перезарядкой, основанным на ударе, обеспечивающим повышение скорости атаки, оно быстро суммируется и усиливается само по себе. Однако это не очень эффективно в фарме, где время восстановления, основанное на ударах, имеет меньшую ценность по сравнению с быстрым перемещением.
# <:EarthsWill:1054837582124560485> Earth''s Will (EW)
- Также необходим в начальстве. Это увеличение урона с перезарядкой, основанной на ударе. Похож на <:SpeedSword:1054837558133129236> SS, не очень эффективен для фарма.
> Примечание:
> Оба <:SpeedSword:1054837558133129236> SS и <:EarthsWill:1054837582124560485> Максимум РЭБ при 20 стеках.
# <:CurvedBlade:1054837628563890197> Изогнутое лезвие (CB)
- Существенное повышение скорости атаки в длительных боях. Не так полезно при боссинге, но все же дает отличный постоянный прирост скорости атаки, если бой длится достаточно долго, чтобы достичь максимального количества стаков.
# <:BurningSword:1054837580388126721> Пылающий Меч (BS)
- Аналогичным образом существенно увеличивается урон от атак в длительных боях. Избегайте использования его в боссах, так как обычно он никогда не достигает более 6 стаков, что делает другие усиления более эффективными. Может быть полезно для фарма этапов на 18 миль в час, чтобы увеличить вероятность убийства мобов и сундука с одного выстрела в конце.
> Примечание:
> Оба <:CurvedBlade:1054837628563890197> CB и <:BurningSword:1054837580388126721> BS максимум при 10 стеках.
> Если <:EarthsWill:1054837582124560485> EW и <:BurningSword:1054837580388126721> BS находятся на одном уровне, они будут иметь одинаковый бафф при максимальном уровне. Однако <:EarthsWill:1054837582124560485> РЭБ обычно достигает максимума быстрее в боях по одной цели, поскольку имеет время восстановления, основанное на ударе.
# <:WindSword:1054837583382847648> Меч Ветра
- Один из наименее полезных навыков в игре. Это может показаться полезным, поскольку повышает скорость атаки, но небольшой плоский положительный эффект редко бывает полезным по сравнению с другими вариантами. Его можно использовать в отдельных нишевых случаях.
# <:IronWill:1054837555482341487> Железная воля (IW)
- Полезно в фарме как постоянно активное усиление урона. Его также можно использовать на боссах ранней игры, прежде чем будут разблокированы лучшие альтернативы. В противном случае его можно использовать только в очень коротких боях.
# ────────── 💪 Баффы ──────────
# ───── 🥦 Активные усиления ─────
-# Навыки с ограниченной продолжительностью, которые пользователь выбирает, когда активировать
# <:FireSword:1054837553951416431> Огненный меч
— Вероятно, единственный общий навык, который продолжает использоваться на протяжении всей игры. В начале игры это будет полезно, пока не будут разблокированы взрывные навыки.
- Это относительно слабый бафф, наносящий урон, и обычно он проигрывает <:Rage:1054837629679575160> Ярости, как только он разблокирован, но он может быть полезен в нишевых боях на время своего действия, не требуя жертвы HP.

# <:Agile:1054837638730879106> Agile
- Хлеб сельского хозяйства. Эффективное сельское хозяйство зависит от быстрого перемещения, и это единственный навык в игре, который увеличивает скорость передвижения.
# <:FlowingBlade:1054837613074321561> Плавающий клинок
- Широко применим в качестве посредственного усиления скорости атаки. Примечательно, что повышение скорости атаки также важно в фарме, в основном для сокращения времени анимации.
- Использование редких карт для пассивных способностей в событиях сделает этот навык очень ценным в середине игры.
# <:Rage:1054837629679575160> Ярость
- Важнейший навык, поскольку он обеспечивает значительное увеличение урона при очень низком уровне здоровья и имеет практически постоянное время безотказной работы.
- В сочетании с механизмом под названием «Rage Swapping» для уменьшения вашего текущего HP или навыками <:LightningBody:1054837662445469706> LB и <:WarriorBurn:1054837661195583558> WB (ниже) для того же эффекта, это один из самых надежных баффов в игре.
- Хотя он почти никогда не является оптимальным при фарме этапов (18 или 4 миль в час), он может быть полезен при фарме более высокого уровня с меньшей скоростью для душ или в закрытых шахтах (<#1125060841155334234>). Он постоянно используется при боссинге, повышении по службе или в других битвах, где HP не имеет значения.
> <:FireSword:1054837553951416431> Огненный меч, <:Agile:1054837638730879106> Проворный, <:FlowingBlade:1054837613074321561> Плавный клинок и <:Rage:1054837629679575160> Rage имеет почти постоянное время работы в сочетании с <:Meditation:1054837527204352010> Medi
# <:LightningBody:1054837662445469706> Тело молнии (LB)
- Сильное повышение скорости атаки на 5 секунд, снижающее текущее здоровье на 50%. Что делает этот навык основным, так это возможность выбирать, когда его активировать, относительно короткое время восстановления и уменьшение HP для повышения <:Rage:1054837629679575160> Rage.
# <:WarriorBurn:1054837661195583558> Warrior Burn (WB)
- Сильное увеличение урона от атак, а также снижение текущего здоровья на 50%.
- Хотя этот навык обычно не разблокируется до поздней игры из-за его высокой стоимости, он полезен во многих ситуациях по тем же причинам, что и <:LightningBody:1054837662445469706>
- Будучи усилением урона, а не скоростью атаки, он также очень хорошо взаимодействует с Familiars (<#1125052747952160888>)
# ───── ⏲️ Пассивные усиления ─────
-# Навыки с ограниченной продолжительностью, которые пользователь напрямую не выбирает, когда активировать
# <:WrafofGod:1054837540970057778> Гнев Божий (WoG)
- Один из наиболее часто используемых навыков в сценариях боссов. Он обеспечивает значительное увеличение урона от атаки на 5 секунд. Сначала он активируется через 20 секунд после начала боя (и это начальное время восстановления нельзя уменьшить с помощью <:Meditation:1054837527204352010> Medi), а затем имеет время восстановления 30 секунд.
- Первый <:WrafofGod:1054837540970057778> WoG почти идеально сочетается с <:noah:1060758788237443132> Ноем (<#1205031896900309052>) в 26-секундном бою с боссом, имея 4-секундное перекрытие.
- Предполагая, что вы используете <:Meditation:1054837527204352010> Medi в начале каждого <:WrafofGod:1054837540970057778> WoG, в длительных боях <:WrafofGod:1054837540970057778> время восстановления WoG будет всего на несколько секунд дольше, чем <:Медитация:1054837527204352010> Меди.
- Можно использовать <:rave:1055598059628789772> Rave с любым другим <:WrafofGod:1054837540970057778> WoG
- Первый <:WrafofGod:1054837540970057778> WoG совпадает со вторым <:StrongCurrent:1054837556778373120> SC при использовании <:Meditation:1054837527204352010> Medi
# <:StrongCurrent:1054837556778373120> Сильный ток (SC)
- Сильное повышение скорости атаки на 6 секунд.
- Несмотря на то, что он хорош против сценических боссов из-за того, как он сочетается с <:WrafofGod:1054837540970057778> WoG в конце боя, сложность с <:StrongCurrent:1054837556778373120> SC заключается в том, что им нелегко управлять, и после первого он не так легко совмещается с <:WrafofGod:1054837540970057778> WoG. Это затрудняет эффективное использование в боях, длящихся дольше, чем стандартный бой с боссом.
# ─────────── 🛡️ Навыки защиты ──────────
# <:DancingWave:1054837660025360464> Танцующие волны (DW)
- Избегает любого урона в течение нескольких секунд. В общем, очень нишевый навык.
- Полезно против Разрушителя в Пространственном Разломе, позволяя игроку уклоняться от всех атак.
- Полезно в поздней игре с боссами, когда у игрока мало здоровья по сравнению с уроном от босса.
# ───── 😵‍💫 Оглушает ─────
> Примечание:
> Все эти умения имеют одинаковый эффект оглушения на 3 секунды.
# <:Blizzard:1054837537312608287> Blizzard
- Имеет самую длинную анимацию, из-за чего активируется медленно. Однако некоторые из этих анимаций также ненадолго приостанавливают таймер битвы.
- Поскольку урон от этого умения незначителен, то стихийная польза по сравнению с <:GigaImpact:1054837516102021211> Giga Impact не очень полезна.
- Сельскохозяйственные льготы будут рассмотрены отдельно.
# <:GigaImpact:1054837516102021211> Гига-удар
- Обычно лучший выбор для одиночных оглушений из-за более короткого времени анимации.
- Используя комбинацию <:GigaImpact:1054837516102021211> Giga Impact и <:Blizzard:1054837537312608287> Blizzard может практически навсегда оглушить врага. Добавив <:DancingWave:1054837660025360464> DW к этим двум навыкам и последовательно складывая их, можно добиться ротации, чтобы полностью избежать любого урона в _**большинстве**_ боев. Это редко бывает лучшим вариантом, поскольку он использует 3 ценных слота навыков, но может быть обязательным в некоторых боях компаньонов в конце игры, где любое попадание означает смерть.
# <:PowerImpact:1054837502499889262> Влияние мощности
- Редко используется из-за 50% вероятности успеха, но может иметь нишевые варианты использования при попытке оглушить врага.
# ───── 🧑‍⚕️ Лечит ─────
# <:ManasBlessing:1054837518668923000> Благословение Маны
- Может быть полезен для регенерации маны в начале игры перед максимизацией навыка спутника Луны «Мана-допинг», но в противном случае он никогда не будет использоваться. Даже в начале игры предпочтительнее использовать регенерацию маны в бросках на повышение убийцы.
# <:GroundsBlessing:1054837631726395506> Благословение земли
- Почти никогда не пригодится.
# <:LifeMana:1054837659052285972> Мана жизни
- Лучшие навыки лечения, но все же редко полезные.
# ────────── 🏃‍♂️‍➡️Навыки движения ──────────
# <:Agile:1054837638730879106> Agile
- Хлеб сельского хозяйства. Эффективное сельское хозяйство зависит от быстрого перемещения, и это единственный навык в игре, который увеличивает скорость передвижения.
# <:Supersonic:1054837538793197628> Supersonic (SS, та же аббревиатура: <:SpeedSword:1054837558133129236> SS <:worrykrow:1180968900905668648>)
- Навык передвижения на большие расстояния со средней перезарядкой, важный навык в сельском хозяйстве.
- Также используется в Forest of Circulation (FoC, см. <#1125060841155334234>) для быстрого перемещения между кристаллами.
# <:Fulgurous:1054837528714293288> Fulgurous (Fulg)
- Навык передвижения на короткие дистанции с низким временем восстановления, необходимый также для фарма.
- Его можно использовать в полностью автоматических сборках FoC, но лучше вручную использовать <:Susonic:1054837538793197628> SS.
- В начале игры это также может быть полезно в некоторых других боях, когда скорость атаки низкая, потому что каждое использование <:Fulgurous:1054837528714293288> Фулга суммирует перезарядку, основанную на ударах (хотя в целом он все еще слаб в боссах).
- Fulgurous требует довольно много маны, поэтому постарайтесь как можно быстрее повысить уровень навыка Mana Dope у компаньона Луны!
> Примечание:
> Если <:Fulgurous:1054837528714293288> Фулг не может убивать мобов с одного удара с самого начала этапа, который вы фармите, это явный признак, что этап выбран слишком высоко. В конечном итоге лучше использовать калькулятор фарма этапов в Master Optimizer: <#1092343850019868682>.
# ────────── <:unknownsword:1057163620703813684> Навыки атаки ──────────
-# В этом руководстве будут игнорироваться общие навыки, потому что они никогда не будут оптимальными, если разблокированы лучшие навыки.
# ───── 🤺 ⚔️ Нанесение ударов, ближняя дистанция ─────
> Примечание:
> Как правило, кулдауны, основанные на ударах, предпочтительнее в боях с высокой скоростью атаки, например, с боссами, потому что их можно повторно активировать гораздо чаще.
# <:FlameSlash:1054837335084236881> Flame Slash (FS) и <:HellfireSlash:1054837443347615796> Hellfire Slash (HFS)
- Основные навыки атаки босса в этой игре, потому что в Эфире, когда мастерство навыков (<#1125052747952160888>) разблокируется, эти навыки атаки огнем улучшаются одними из первых.
- Большинство игроков в конечном итоге сосредотачиваются на уроне от стихии огня. <:FlameSlash:1054837335084236881> особенно важен, поскольку его уровень будет повышаться путем покупки редких карт в событиях, что важно для максимизации редких пассивных навыков ( <:SpeedSword:1054837558133129236> SS, <:EarthsWill:1054837582124560485> EW, <:BurningSword:1054837580388126721> BS, <:FlowingBlade:1054837613074321561> Flowing).
# <:PowerStrike:1054837360354938950> Power Strike (PS) и <:GigaStrike:1054837450415022140> Giga Strike (GS)
- Навыки босса для учетной записи, ориентированной на землю. В начале игры, до того как мастерство навыков будет разблокировано, они могут быть равны или лучше, чем огненные атаки, описанные выше, поэтому определите для себя, какие навыки атаки лучше всего подходят для вашей сборки.
# <:WaterSlash:1054837500012671046> Водный удар (WS)
- Почти бесполезно. Основным недостатком является длительная блокировка анимации, во время которой невозможно использовать другие навыки (потому что, как еще вы сможете нанести 7 ударов, я полагаю <:worrykrow:1180968900905668648>).
- Этот навык можно использовать против некоторых врагов стихии огня (в основном, только в битве с товарищами Михо), если ваш профиль стихийного урона относительно сбалансирован, но для учетной записи, ориентированной на огонь, навыки огненного удара все равно будут гораздо более эффективными.
# <:DemonHunt:1054837525799248034> Охота на демонов (DH)
- Самый мощный ударный навык в игре и, следовательно, одна из самых мощных атак для убийцы.
- Он попадает 7 раз: первые 6 имеют урон, указанный в подсказке навыка, а 7-й - в 6 раз больше, что в сумме дает 12-кратный урон.
- Обычно низкий приоритет для разблокировки из-за его цены и возможности сосредоточиться на уроне от огня с помощью Black Orb (<#1121538334523654154>). В основном полезно для включения пробуждения орра.
- Это может быть жизнеспособным навыком третьей атаки, когда ваш профиль стихийного урона относительно сбалансирован, но в противном случае этот навык останется бесполезным до конца игры, когда он снова станет самым мощным навыком благодаря усовершенствованию Мастерства навыков и обеспечит важные механические преимущества благодаря анимации остановки времени.
# ───── 🤺 🏹 Нанесение ударов, дальняя дистанция ─────
# <:LightningStroke:1054837501195468851> Удар молнии (LS) и <:RedLightning:1054837517523882115> Красная молния (RL)
- Основные навыки ветра, используемые на протяжении всей игры. Они необходимы для фарма из-за своей дальней дистанции, а против крупных целей (Древний дракон, Разрушитель и т. д.) они также могут быть отличными навыками босса.
- Обычно предпочтение отдается навыкам огненной/земляной атаки, но замена некоторых из них для больших боссов может быть полезной.
- Необходим в FoC при улучшении.
> Примечание:
> Если один из этих навыков активен при выпуске <:rave:1055598059628789772> Rave или <:DemonHunt:1054837525799248034> DH или Familiars (<#1125052747952160888>), все молнии ударят до того, как навык будет завершен (или в <:rave:1055598059628789772> Кейс Рейва, даже активированный). Это может быть полезно для получения дополнительных ударов молнией во время основных усилений.
# <:ThunderSlash:1054837355497922641> Thunderbolt Slash (TS) и <:ThunderboltSlash:1054837459994812426> Thunderbolt Slash (TBS)
- Навыки фарма на дальней дистанции, которые поражают монстра только один раз. По этой причине они, как правило, полезны только при фарме на 4 мили в минуту или в других нишевых сценариях, где ценен более высокий урон и более короткое время восстановления по сравнению с навыками молнии.
# ───── ⌛ ⚔️ На основе таймера, ближний радиус действия ─────
# <:PillarofFire:1054837539896295484> Огненный Столп (PoF)
- Взрыв на основе таймера, создающий кучу огненных столбов. Если все столбы поражены (что не гарантируется для меньших целей), это нанесет примерно в 11,4 раза больше урона, чем указано во всплывающей подсказке.
- Хотя этот навык очень мощный и может быть полезен в борьбе с боссами и против продвижения Эфира до того, как Мастерство навыков улучшит навыки огненного удара, после этого момента <:PillarofFire:1054837539896295484> PoF становится практически бесполезным.
# <:HotBlast:1054837499027013642> Hot Blast и <:FireBlast:1054837514675966034> Fire Blast
- Практически бесполезен на протяжении всей игры. Они могут показаться привлекательными, но время восстановления, основанное на таймере, делает их менее эффективными, чем другие варианты.
# ───── ⌛ 🏹 На основе таймера, большой радиус действия ─────
# <:Flamewave:1054837524343824444> Flamewave (FW)
- Приличный навык фарма из-за его большой дальности, особенно в начале игры, но он быстро исчезает из-за низкой скорости перемещения и длительного времени анимации по сравнению с лучшими вариантами, такими как <:Blizzard:1054837537312608287> Blizzard ниже.
# <:Blizzard:1054837537312608287> Метель (Метель)
- Самый важный навык атаки в фарме из-за его огромного радиуса действия и гарантии поражения врагов с одного выстрела при фарме, а также гораздо более высокого базового урона, чем у других навыков фарма.
# <:IceShower:1054837351270060173> Ледяной дождь и <:IceTime:1054837455246868560> Ice Time
- Практически бесполезен на протяжении всей игры. Несмотря на большую дальность действия, редкость их ударов делает их менее надежными для фарма, чем молнии. Они обеспечивают небольшой эффект замораживания, но это никогда не бывает полезным.
# ────────── 🧬 Бессмертные навыки ──────────
> Ссылка: [[skills_immortal_skills|Бессмертные навыки]]
# <:rave:1055598059628789772> Рейв
- Навык, который записывает ваш урон, чтобы вы могли использовать его весь сразу, чтобы нанести огромный урон. Имеет 2 активации:
1. Начать запись повреждений. При первом нажатии запускается 5-секундный таймер записи.
2. По истечении 5 секунд записи урона вторая активация сбрасывает записанный урон.
- Незаменим в боях с одиночными целями.
- Поскольку он записывает урон в течение 5 секунд, он очень хорошо взаимодействует со всеми другими короткими баффами, создавая мощный взрыв в течение небольшого периода. Если возможно, сохраните его для использования с духом <:noah:1060758788237443132> Ноя.
> ⚠️ Внимание:
> Будет записан только урон, нанесенный 1 цели! Поэтому, если вы начнете запись моба, убьете его и продолжите атаковать других мобов во время фазы записи, будет высвобожден только урон, нанесенный первому мобу!
# <:Mantra:1054837329367420998> Мантра
- Единственный постоянный пассивный навык в этой игре. Вам не нужно включать его в свой набор навыков, потому что, как только он будет разблокирован, он обеспечит постоянное повышение как HP, так и атаки.

# ─────────────── TL;DR ───────────────

- Используйте <:Meditation:1054837527204352010> Medi, чтобы улучшить свои навыки!
- <:SpeedSword:1054837558133129236> SS и <:EarthsWill:1054837582124560485> EW во всех боссинговых или подобных боях! <:CurvedBlade:1054837628563890197> CB и <:BurningSword:1054837580388126721> BS ТАКЖЕ во всех продолжительных боях!
- <:WrafofGod:1054837540970057778> WoG является центральным элементом большинства сборок боссов! Обходите эту проблему и комбинируйте усиления в этот период, чтобы получить мощный взрыв!
- <:Rage:1054837629679575160> — один из самых полезных навыков! Также узнайте, как менять ярость!
- <:FlameSlash:1054837335084236881> FS и <:HellfireSlash:1054837443347615796> HFS — основные навыки атаки босса для большинства людей!
- Перезарядка на основе ударов > перезарядка на основе таймера для босса!
- <:Agile:1054837638730879106> Agile, <:Susonic:1054837538793197628> SS и <:Fulgurous:1054837528714293288> необходимы в сельском хозяйстве, потому что сельское хозяйство - это быстрое движение! <:Fulgurous:1054837528714293288> ест ману, поэтому повышайте уровень Мана-допинга Луны!
- <:Blizzard:1054837537312608287> Blizz и <:RedLightning:1054837517523882115> RL будут самыми важными навыками атаки на дальней дистанции в фарме 18mpw! Иногда добавляйте <:Flamewave:1054837524343824444> , а иногда учитывайте <:ThunderSlash:1054837355497922641> TS / <:ThunderboltSlash:1054837459994812426> TBS на меньшем количестве целевых этапов 4mpw!
- Оформите заказ <#1131131863117856920>, чтобы получить некоторые базовые сборки, и используйте то, что вы узнали здесь, чтобы адаптировать сборки для своей учетной записи!
- Никакая информация не идеальна, поэтому лучшие сборки для вашего аккаунта будут найдены путем экспериментов! Никогда не забывайте проявлять любопытство и продолжайте пробовать что-то новое!
