VALUES (
  'skills_skill_functions',
  'skills',
  'Skill Functions',
  'Информация о вкладке «Навыки» и ее функциях.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/skills/skill_functions/image.png
1 — см. рисунок выше; лучший элемент для использования против определенного типа
2.1 - По мере увеличения *Уровня навыка*; АТК вашего атрибута увеличивается
2.2 – Каждые 5 уровней *Владения навыками* сила всех атрибутов АТК увеличивается на 7%.
3. Большинство навыков имеют перезарядку или требуют для активации ударов или маны.
4. Некоторые навыки наносят урон, увеличивают урон, увеличивают скорость атаки, лечат и т. д.
5. Проверьте <#1052865880146579469>, чтобы узнать, какой набор навыков использовать.
6. Понять, что делает каждый навык; пожалуйста, прочитайте это.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/skills/skill_functions/image.png
**Формула урона навыка (Skill Dmg Formula)**
Формула (внутриигровые переменные оставлены как в оригинале):
```Итог = Unbuffed atk * (1+ total skill atk buffs %/100) * (1+ wisdom of war%/100) * (1 + (Comp Element % + Understanding% + Skill Prof% + Relic Element% + Black Orb Equipment topstat%)/100) * (1+ Black Orb substat%) * (1+ Black Orb mob/boss%) * (skill damage %/100)```
