**Информация об освоении навыков**
1. Разблокировано в Ether
2. Мастерство навыков. Улучшайте свои навыки, здоровье атаки, опыт и золото, используя очки мастерства. Награды также включают в себя алмазы, M1 и легендарных питомцев.
3. Очки мастерства можно получить за выполнение достижений, связанных с навыками, товарищами и духом.
4. Необходимо заполнить всю страницу, чтобы перейти к следующей странице.
5. На странице 1 разблокируйте <:FireSlash:1054837281246163054> <:FlameSlash:1054837335084236881> <:HellfireSlash:1054837443347615796> как можно скорее. Или еще.
