INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'skills_skill_refinement',
  'skills',
  'Skill Refinement',
  'Информация о совершенствовании навыков

**Улучшение навыков (Skill Refinement)**
• Камни усовершенствования можно получать, совершенствуя отдельные навыки.
• Для старта поместите подходящий навык в слот Skill Refinement.
• Количество слотов растет вместе с уровнем Skill Proficiency.
• В слот можно поставить только активные атакующие навыки уровня 10+.
• Навыки более высокого грейда совершенствуются дольше.
• Количество получаемых камней растет с вашим Skill Proficiency.

*Ниже - рекомендательный приоритет. Owned Effect глобальный. Фокус на атаке/крите. Если вам важнее уклонение/HP/точность, смещайте приоритеты под себя.*
*Путь прокачки: от обычного (Common) к мифическому (Mythic). Выбор частично субъективный.*

**Мифический (Mythic)**
• <:DemonHunt:1054837525799248034> - Attack %
• <:PillarofFire:1054837539896295484> - Critical %

**Легендарный (Legendary)**
• <:FireBlast:1054837514675966034>, <:ThunderboltSlash:1054837459994812426> - Attack %
• <:IceTime:1054837455246868560>, <:RedLightning:1054837517523882115> - Critical %

**Редкий (Rare)**
• <:WaterSlash:1054837500012671046>, <:ThunderSlash:1054837355497922641> - Attack %

**Хороший (Great)**
• <:HotBlast:1054837499027013642> - Attack %
• <:IceShower:1054837351270060173>, <:LightningStroke:1054837501195468851> - Critical %

**Обычный (Common)**
• <:LightningSlash:1054837295062188053> - Attack %
• <:IceStone:1054837289466986589> - Critical %

**Средняя стоимость Refinement Stones**
Средняя цена за одну линию целевого максимального ролла (обычно +20% Dmg) при расчете с допущением уровня 100:

0 зафиксировано - 480
1 зафиксировано - 1200
2 зафиксировано - 2400
3 зафиксировано - 4800
4 зафиксировано - 12000
Все 5 линий по 20% - 20880

## Важный комментарий по разбросу
Разброс очень большой: кому-то хватает около 5000 stones, а кому-то может понадобиться около 40000. Осторожнее с роллами на ключевых навыках.

## Приоритет навыков
1. Самые часто используемые навыки (<:FlameSlash:1054837335084236881> / <:RedLightning:1054837517523882115> / <:DemonHunt:1054837525799248034> и т.д., зависит от вашего аккаунта и сборок). Для них приоритет - DMG Increase (в идеале +20% на всех линиях). Для чисто фарм-навыков вместо этого можно брать Cooldown Reduction.
2. Навыки, дающие Crit DMG % через refinement Owned Effect (<:PillarofFire:1054837539896295484> / <:IceTime:1054837455246868560> и т.д.). Для них достаточно получить мифические роллы по всем линиям с любыми бонусами, чтобы открыть эффект.
3. Навыки, дающие Character ATK % (<:DemonHunt:1054837525799248034> / <:HellfireSlash:1054837443347615796> и т.д.). Подход тот же: все линии в mythic с любыми бонусами ради Owned Effect.
4. Остальные навыки.
