VALUES (
  'slayer_playbook_companion_passive_opinion',
  'slayer-playbook',
  'Companion Passive   Opinion',
  'Руководство по Companion Passive - субъективное мнение
Мой рейтинг: <#1270124713758425138>, если нужен полный контекст.
Если не видите пассивную страницу, значит она у вас еще не разблокирована. Этот файл - быстрый ориентир.

***Элли (Ellie)***

