INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'spirit_detailed_proscons_list_for_spirits',
  'spirit',
  'Detailed ProsCons list for Spirits',
  'Подробный список с описанием плюсов и минусов каждого духа и того, для чего они лучше всего подходят.
# **Loar <:Leg_loar:1060758780775764058> : **
__**Плюсы**__
- 1,1x – 1,8x урон только БОССУ
- Лучший дух на уровне босса.

__**Минусы**__
- Навык не влияет на обычных мобов.
- Необходимо также улучшить, чтобы полностью использовать Лоар.

__**Применение**__
- Используется в рекламных акциях, сценическом боссе, битве компаньонов, GK, SH, разломе измерений.

**__Общий__**
Только дух-босс, кроме босса, этот дух мало что делает, кроме предоставления статистики, если он пробужден выше.


# **Ной <:Leg_noah:1060758788237443132> **
__**Плюсы**__
- 1,2-2-кратный урон за последние 5 секунд боя с таймером.
- Лучший дух для босса сцены, поскольку он хорошо сочетается с рейвом вог.
- Лучший дух для использования в качестве духа-компаньона для повышения на 10%.
- Не требует раннего улучшения для полного использования.

__**Минусы**__
- В очень длительных битвах и битвах по зачистке мобов другие духи будут более полезны, чем Ной.
- Способность срабатывает только один раз за битву (не срабатывает снова, если вы получаете таймер и он снова падает до 5 секунд).

**__Использование__**
- Используется в промоушенах, сценическом боссе, битве компаньонов, GK, SH, разломе измерений, тренировочном молоке, DV и убежище спящего пламени.
- Достойный заменитель TC и FOC, если подходящего духа у вас нет.

**__Общий__**
В основном это властный дух, но он также универсален и в других областях.


# **Радон <:Leg_radon:1060758791207002131> **
**__Плюсы__**
- 1,1х – 1,8х любым мобам и боссам, но только с 70% хп и выше.
- Если вы можете фармить за один раз, это лучше, чем Заппи.
- Дух босса в поздней игре, который может заменить Салу на уровне босса в зависимости от настройки навыков.

__**Минусы**__
- Необходимо также улучшить, чтобы полностью использовать.

__**Применение**__
- Босс сцены, регенерация ГК, ШХ, ферма сцены.

__**Общий**__
Дух для финальной игры с определенными предварительными условиями, прежде чем он будет использован в качестве босса уровня.
# ** Zappy <:Leg_zappy:1060758779488112701> **
** __Плюсы __ **
- Дух ветроэнергетики, который не крадет ресурсы у другого элемента.
- Даже если вы оффлайн-фермер, вы все равно можете создать zappy.
- Мгновенное убийство мобов с уровнем здоровья ниже 14-30%.

** __Минусы__ **
-    Никто

** __Использование__ **
- Сценический фарм, ТК, ФОК, КМ, внешний вид и сюжетная битва за зачистку мобов, промо (ситуативные).

** __Общий__ **
Хороший дух, который имеет больше применений, чем его аналог ветра, и вам не нужно улучшать его, чтобы он был полезен.

# ** Карт <:Leg_kart:1060759190672515092> **
** __Плюсы __ **
- Уменьшает здоровье моба на 13% - 25% при первом ударе.

** __Минусы__ **
- Лучше всего только для FOC.
- Для эффективности требуется E3+

** __Использование__ **
- FOC, внешний вид и сюжетная битва для зачистки мобов. TC, фарм этапов и CM в зависимости от ситуации.

** __Общий__ **
Хороший дух, в основном для FOC, хотя вам может не хватать духовного корма для улучшения из-за сосредоточения внимания на zappy.

# ** Хер <:Leg_herh:1060758774421409792> **
** __Плюсы__ **
- Можно использовать в рифте или DV.

** __Минусы__ **
- Навык Херха не дает ощутимой прибавки к возможностям игрока в боях, он не несет никакой пользы и лучше быть кормом.
- Блокирует очки мастерства навыков от пробуждения духов ветра.
- Всякий раз, когда его умение срабатывает, происходит задержка. Это затрудняет использование на этапе фермы.

** __Использование__ **
- Корм ​​для заппы и картинга.

** __Общий__ **
Этот дух не имеет никакой пользы, кроме получения очков мастерства. Не инвестируйте в Herh, если вам не нужно получить его в эпохальном/бессмертном режиме за 12/12.
# ** Тодд <:Leg_todd:1060758778221436989> **
** __Плюсы __ **
- 1,1x – 1,8x прирост золота.
- Дух водного земледелия, который не крадет ресурсы у другого элемента.

** __Минусы__ **
- Навык не работает оффлайн.
- Если вы оффлайн-фермер, Луга будет лучшим выбором для строительства.
- Необходимо улучшить, чтобы полностью использовать.

** __Использование__ **
- Стадия фермы и CM.

** __Общий__ **
Лучший водный дух за золото. Золото помогает новым игрокам быстрее прогрессировать с помощью алмазных квестов или улучшения статистики. Для тех, кто приближается к увеличению золота в 1,2 миллиона+, Луга начинает иметь приоритет.

# ** Луга <:Leg_luga:1060758784106057880> **
** __Плюсы __**
- Увеличение опыта в 1,1–1,8 раза.
- Дух водного земледелия, который не крадет ресурсы у другого элемента.
- Хорошо для оффлайн игроков за TC.

** __Минусы__ **
- Необходимо улучшить, чтобы полностью использовать.
- Подходит для этапной фермы только в том случае, если у вас есть ограничение на улучшение.

** __Использование__ **
- ТК. Стадия фарма и КМ в зависимости от ситуации.

** __Общий__ **
Не идеальный ранний водный дух для создания. Создавайте это только после того, как закончите с Тоддом.

# ** Ковчег <:Leg_ark:1060758770373886002> **
** __Плюсы __**
- Таймер заморозки, чтобы разрешить двойное рейв в GK.

** __Минусы__ **
- Время останавливается только один раз за бой.
- Будет неправильно выбрано время для Ноя и Вога в сценической битве.

** __Использование__ **
- Некоторые битвы за внешний вид. ГК ул. и регенерация.

** __Общий__ **
Очень нишевый дух для использования. Если другие ваши духи пробуждены, а Арк нет, Арк может быть даже бесполезен для битвы за внешний вид. Как правило, это будет последний водный дух, который будет создан после того, как Тодд и Луга станут A6E5.
- Создание Ноя может быть менее полезным в начале игры для новых игроков, у которых нет <:rave:1055598059628789772> и <:WrathOfGods:1054837540970057778>. Как указано выше в разделе **Минусы**, другие духи будут более полезны в длительных битвах.
