INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'spirit_fountain_of_circulation',
  'spirit',
  'Fountain of Circulation',
  'Объясняет функцию «Фонтана обращения».
# Фонтана обращения
Разблокированная на S300 система «Фонтан кровообращения» повышает уровень шести ваших духов самого низкого уровня до уровня вашего шестого духа самого низкого уровня. Эта система полезна для менее часто используемых духов, поскольку позволяет использовать их без специального улучшения.
<:noah:1060758788237443132> <:zappy:1060758779488112701> <:loar:1060758780775764058> <:todd:1060758778221436989> <:radon:1060758791207002131><:mum:1060758787092402237>
Итак, у нас есть эти 6 духов.
Весь уровень скажем 75
Мы можем пригласить этих <:herh:1060758774421409792> <:ark:1060758770373886002> <:worrybo:1060758772752056380> <:kart:1060759190672515092> <:sala:1060758775839080598> <:luga:1060758784106057880> неудачников.
Допустим, уровень 50.
Присоединяйтесь к культу
А те духи-неудачники, которые имеют 50-й уровень, потеряют свои уровни и все ресурсы; будет возвращен. (Куб/Кристалл)
Доводим их всех до 75 уровня.
Поскольку они состоят в большом культе духов высокого уровня, они получают свою силу.
1. Фонтан Круговорота автоматически регистрирует шесть духов высших уровней как Высшие Духи.

2. Когда вы экипируете дух в слот, его уровень будет скорректирован в соответствии с самым низким уровнем среди Высших Духов.

3. Если вы экипируете в слот духа, уровень которого уже повышен, ресурсы, использованные для повышения уровня, будут возвращены.

4. Духи, установленные в слоте, не могут быть повышены; вы можете повысить их уровень снова только после того, как вытащите их из слота.

5. Если вы обладаете духом более высокого ранга, чем самый высокий уровень среди Высших Духов, кнопка сброса уровня будет активирована для духа с самым низким уровнем среди Высших Духов.

6. Нажатие на кнопку сброса установит уровень Высшего Духа на 0, а ресурсы, затраченные на его повышение, будут возмещены.
Пробуждение:
После 12/12 Мифических Духов вы разблокируете это.
Выберите вариант с 4 равными полосками и пропустите при появлении запроса.
Он дает несколько алмазных наград и в целом повышает характеристики на 20%+.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/spirit/fountain_of_circulation/image.png
