INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'spirit_spirit_exchange_system_meloning',
  'spirit',
  'Spirit Exchange System ‘Meloning',
  'Информация о системе обмена духами.
Представляем «Систему обмена дынь» — получите <:Melon2:1134338854657208412>, потребляя легендарных и героических духов.

**Предупреждение: этот подход не рекомендуется из-за низкой эффективности по стоимости.**

Требование: достичь уровня 400.

<:Melon2:1134338854657208412> Варианты: Огонь, Вода, Воздух, Земля и Радуга.

<:Melon2:1134338854657208412> может служить заменой духов того же элемента во время Пробуждения/Улучшения, когда критерии требуют материального духа того же элемента. Однако они неприемлемы, когда требуется точное совпадение.

<:Melon2:1134338854657208412> Курсы обмена:
1. Случайная дыня: обменяйте 1 легендарного духа + 1 эпического духа. Результат включает 30% шанс получить дыню другого элемента (розыгрыш повторяется три раза) и 10% шанс получить радужную дыню.
2. Конкретная дыня: обменяйте 1 легендарного духа + 2 эпических духа на дыню нужного типа.
