INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'spirit_spirit_overview',
  'spirit',
  'Spirit Overview',
  'Информация об уникальных способностях и навыках каждого духа.

**Земля (Earth)**
<:Radon:1129588019763089488> - Увеличивает урон по врагам на 10-80%, когда HP цели выше 70%.
<:Noah:1129588498375123034> - За 5 секунд до конца боя повышает ваш урон в 1.2-2 раза.
<:Loar:1129588013383561327> - Увеличивает урон навыков по боссам на 10-80%.

**Огонь (Fire)**
<:Mum:1129588014088200223> - Урон навыков по обычным монстрам +10-80%.
<:Sala:1129588010032308294> - Каждые 12 секунд после начала боя наносит 6-10% от оставшегося HP цели.
<:Bo:1129588021486964836> - Общее HP увеличивается на 100-500%.

**Вода (Water)**
<:Ark:1129588011269636208> - Через 8 секунд после начала боя останавливает время на 4-10 секунд. Один раз за бой.
<:Todd:1129588015925297203> - Шанс 10-80% получить 2x Gold при получении золота.
<:Luga:1129588499528552508> - При получении EXP есть шанс 10-80% получить двойной EXP.

**Воздух (Air)**
<:Kart:1129588496638681181> - При первой атаке по обычному монстру снижает его HP на 13-25%.
<:Herh:1129588012427251722> - Skill cooldown + восстановление 4-6% каждые 10 секунд.
<:Zappy:1129588017493979258> - Мгновенно убивает обычных монстров, если у них меньше 14-30% HP.
