INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'spirit_spirits',
  'spirit',
  'Spirits',
  'Информация обо всех системах духов.

# Обзор
Духи дают персонажу дополнительные характеристики и пассивные навыки. Они открываются **после прохождения Stage 100** и критически важны для роста общего урона.

Основные системы прокачки:
* **Эволюция (Evolution)** - получение духов более высокой редкости.
* **Повышение уровня (Leveling)** - повышение уровня духа и его характеристик.
* **Усиление навыков (Skill Enhance)** - усиление пассивных навыков (Legendary+).
* **Пробуждение (Awaken)** - повышение редкости выше Legendary.

## Основной дух-партнер
* Можно назначить **одного основного духа-партнера**.
* Этот дух получает **+10% к эффекту своего навыка**.

## Система эволюции (Evolution)
* Используйте дубликаты духов для создания духов более высокого тира.
* Порядок редкости: `Common -> Great -> Rare -> Epic -> Legendary -> Mythic -> Immortal -> Ancient`.

## Система повышения уровня (Leveling)
* Используйте **Enhance Cubes + Mana Crystals** для повышения уровня духа.
* Чем выше уровень, тем сильнее базовые характеристики.

## Стоимость в Diamonds
В **среднем** получение Legendary духа через combine обходится примерно в **46.7k diamonds**.

> **Примечание:** это долгосрочное среднее значение. Поскольку попытки распределяются между 12 духами, фактический результат у разных игроков может сильно отличаться, и Legendary не гарантируется в пределах среднего значения.

## Система усиления навыков (Skill Enhance)
* Доступна только для духов Legendary и выше.
* Использует **Legendary дубликаты или духов того же атрибута**.
* **Пример:**
  * <:Leg_zappy:1060758779488112701>
  * E1 = Легендарный
  * E2 = 1 <:Leg_zappy:1060758779488112701>
  * E3 = 2 того же атрибута ( <:Leg_zappy:1060758779488112701> <:Leg_herh:1060758774421409792> <:Leg_kart:1060759190672515092>)
  * E4 = 1 <:Leg_zappy:1060758779488112701>
  * E5 = 2 того же атрибута ( <:Leg_zappy:1060758779488112701> <:Leg_herh:1060758774421409792> <:Leg_kart:1060759190672515092>)

> **Примечания:**
> * Улучшение навыка постоянное.
> * Оно применяется ко всем текущим и будущим копиям этого духа.
> * Улучшение не теряется, даже если вы скормите/объедините этого духа.

https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/spirit/spirits/image.png

## Система пробуждения (Awaken)
Awakening позволяет духам превзойти Legendary, повышая и характеристики, и лимит уровня.

* **Типы материалов:**
  * **Copy:** точный дубликат этого же духа.
  * **Fodder:** любой Legendary дух того же атрибута.

### Мифический (Mythic)
> **Общая стоимость:** 3x Copies + 7x Fodder

**Пример:**
* <:Leg_zappy:1060758779488112701>
* A0 = Легендарный
* A1 = 1 <:Leg_zappy:1060758779488112701>
* A2 = 2 на корм ( <:Leg_herh:1060758774421409792> <:Leg_kart:1060759190672515092>)
* A3 = 1 <:Leg_zappy:1060758779488112701>
* A4 = 2 на корм ( <:Leg_herh:1060758774421409792> <:Leg_kart:1060759190672515092>)
* A5 = 1 <:Leg_zappy:1060758779488112701>
* Mythic = 3 на корм ( <:Leg_herh:1060758774421409792> <:Leg_kart:1060759190672515092>)

### Бессмертный (Immortal)
> **Требование:** чтобы начать прогресс Immortal (A6+), все 12 духов должны быть Mythic (A6).
> **Общая стоимость:** 3x Copies + 7x Fodder

**Пример:**
* Mythic <:Leg_zappy:1060758779488112701>
* A6 = Мифик (Mythic)
* A7 = 1 <:Leg_zappy:1060758779488112701>
* A8 = 2 на корм ( <:Leg_herh:1060758774421409792> <:Leg_kart:1060759190672515092>)
* A9 = 1 <:Leg_zappy:1060758779488112701>
* A10 = 2 на корм ( <:Leg_herh:1060758774421409792> <:Leg_kart:1060759190672515092>)
* A11 = 1 <:Leg_zappy:1060758779488112701>
* Immortal = 3 на корм ( <:Leg_herh:1060758774421409792> <:Leg_kart:1060759190672515092>)

### Древний (Ancient)
> **Требование:** чтобы начать прогресс Ancient (A12+), все 12 духов должны быть Immortal (A12).
> **Общая стоимость:** 4x Copies + 4x Fodder + 1000 Light Shards

**Пример:**
* Immortal <:Leg_zappy:1060758779488112701>
* A12 = Бессмертный (Immortal)
* A13 = 1 <:Leg_zappy:1060758779488112701>
* A14 = 2 на корм ( <:Leg_herh:1060758774421409792> <:Leg_kart:1060759190672515092>)
* A15 = 1 <:Leg_zappy:1060758779488112701>
* A16 = 2 на корм ( <:Leg_herh:1060758774421409792> <:Leg_kart:1060759190672515092>)
* A17 = 1 <:Leg_zappy:1060758779488112701>
* Ancient = ( <:Leg_zappy:1060758779488112701> + 1000 <:light_shard:1400147911526056067> )

**Частые вопросы (FAQ):**
• Уровень навыка не влияет на редкость духа: у Mythic духа может быть Skill Level 1.
• Имеет смысл рано тратить Emeralds на открытие дополнительных слотов духов, так как духи дают очень ценные статы.
• Приоритет духов зависит от вашего аккаунта и целей; ориентируйтесь на элементальные приоритеты и контент.
• Ценность обычного уровня духа относительно Awaken-уровня зависит от конкретного духа. В среднем A2 обычно ценнее E3, а A4 часто ценнее последующих уровней enhance. При этом A5 не всегда дает столь же сильный прирост, поэтому на этом этапе иногда выгоднее инвестировать в Skill Enhance.

