<:Leg_herh:1060758774421409792> Корм, A0-Древний, E1-E5

<:Leg_sala:1060758775839080598> A0-Мифический, E1-E5, Мифический-Древний

<:Leg_mum:1060758787092402237> A0-A2, E1-E5, A3-Древний

<:Leg_bo:1060758772752056380> Корм, A0-Древний, E1-E5

<:Leg_todd:1060758778221436989> E1-E5, A0-Древний

