3 духа, которых обычно улучшают последними. <:Leg_herh:1060758774421409792> <:Leg_bo:1060758772752056380> <:Leg_ark:1060758770373886002>
- Эти духи полезны только в отдельных ситуациях.
- Порядок основан на приросте Mastery Point.
- По совокупной пользе и приросту Mastery Point Ark/Bo считаются одними из наименее выгодных для раннего апгрейда.
- Иногда утверждают, что Ark лучше, но оценивайте такие советы критически: часто это либо нехватка понимания, либо троллинг.
