https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/spirit/what_to_enhanceawaken_first/image.png
# Оптимизация духов в начале

Когда мы начинаем с духами, мы хотим, чтобы в качестве палочек наших характеристик выступали два духа, которых мы рано пробуждаем до A6 (некоторые игроки могут назвать это мифическим натиском),
и два духа с хорошими множителями навыков, поэтому в целом мы получаем максимальную выгоду с наименьшим количеством духов. Поскольку характеристики усреднены между всеми тремя экипированными духами, наличие двух пробужденных духов с высоким уровнем компенсирует недостаток характеристик на улучшенном третьем.

Мы берем по 1 духу от каждого элемента, чтобы оптимизировать наши ресурсы.
# Для пробуждения
Мы используем <:Leg_sala:1060758775839080598> и <:Leg_zappy:1060758779488112701>.

# Для усиления навыков
Мы используем <:Leg_loar:1060758780775764058> и <:Leg_todd:1060758778221436989>.

<:Leg_sala:1060758775839080598> обладает одним из, если не самым эффективным навыком, даже на уровне 1, который получает меньшую выгоду от улучшений, чем другие.
Вдобавок ко всему, у него самые высокие показатели золота и атаки среди всех духов. Это делает их отличной целью для пробуждения. Они могут служить надежной заменой на ранних этапах, когда у вас нет оптимального расположения духа фермерства, но при этом обеспечивают хорошие навыки для боссов и повышения по службе.

<:Leg_zappy:1060758779488112701> — наш выбор духа ветра, поскольку он обладает наиболее эффективными навыками среди них. Почти всегда это прямое обновление по сравнению с картом. Хотя их улучшения действительно хороши, ради стратегии мы сначала пробуждаем их к А6.

<:Leg_loar:1060758780775764058> используется из-за его большого мастерства. На E5 он дает вам на 80% больше урона по боссам без каких-либо условий. Хотя он и не работает в некоторых режимах, таких как Rift и Dragon Valley, его ценность в битвах с боссами стадий и повышении более чем того стоит.

<:Leg_todd:1060758778221436989> — лучший водный дух из ранних. Золото пользуется огромным спросом в начале и большей части середины игры. На E5 они дают вам на 80% больше золота, что является существенным улучшением вашего прироста алмазов и урона в секунду в виде урона от «Удара смерти».

С этими четырьмя у нас может быть две схемы: одна ориентирована на боссов, другая ориентирована на фарм.
# Оптимизация духов в midgame

Дополняя свой список духов и работая над созданием Бессмертных духов, после достижения 12/12 мифов вы можете начать работать над улучшениями.
В Immortal приоритет пробуждения меняется по мере расширения ваших возможностей.

Огонь: Сала A6 -> Мама E5 -> Мама A6 -> Бо A6 -> Мама A12 -> Сала E5 -> Сала A12 -> A12 Bo -> A18 Мама -> A18 Сала
Земля: Лоар A6E5 -> Ной E5 -> Ной A6 ​​> Радон A6 -> Ной A12 -> Лоар A12 -> A12 Радон -> A18 Ной -> A18 Лоар
Ветер: Заппи A6E5 -> Карт A6 -> Херх A6 -> Заппи A12 -> Карт E5 -> A12 Карт -> A12 Херх -> A18 Заппи
Вода: Тодд Е5 -> Тодд А6 -> Луга А6 -> Арк А6 -> Луга Е5 -> Луга А12/Тодд А12 -> А12 Арк -> А18 Луга -> А18 Тодд

При обновлении до Ancient Spirits рекомендуемая установка — 2 Босса и 2 Фермы, Лоар, Ной, Мама, Заппи.
Если вы хотите улучшить Салу, Лугу, Тодда и т. д., сделайте это после [[character_class|Nova]]/[[character_constellation|Constellations]] и Orr24, поскольку осколки — это ресурс премиум-класса.
