INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'stage_stage_boss_info',
  'stage',
  'Stage Boss Info',
  'Информация об этапах Босса.
Все боссы на этапе являются нейтральным элементом, поэтому ни один навык не будет иметь особого преимущества в боях. Если бы они это сделали, это было бы видно слева от их шкалы здоровья.

Если вы оффлайн-фермер, вы получите вознаграждение в зависимости от максимального пройденного вами этапа, поэтому чрезвычайно важно продвигаться вперед, когда это возможно. Вы также будете зарабатывать больше золота в автономном режиме в зависимости от вашего текущего процента золота, поэтому перед выходом в автономный режим измените свой самый высокий уровень пробуждения духа/самый высокий уровень золота.

Еще одним преимуществом продвижения является универсальный прирост золота, который вы получаете за каждые пройденные 10 этапов, обычно он будет с шагом 0,2.
