INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'stage_stage_farm_builds',
  'stage',
  'Stage Farm Builds',
  'Сборки для сценического фарма.
**Минимальная** комплектация для поэтапного фарма.

<:skillbook:1290965217345540188> **Развитие навыков**
**• Ранняя игра**
<:Fulgurous:1054837528714293288> <:ThunderSlash:1054837355497922641> <:ThunderboltSlash:1054837459994812426> <:Flamewave:1054837524343824444> <:IronWill:1054837555482341487> /
<:FireSword:1054837553951416431>

**• Средняя игра**
<:Fulgurous:1054837528714293288> <:Supersonic:1054837538793197628> <:Flamewave:1054837524343824444> <:RedLightning:1054837517523882115> <:ThunderboltSlash:1054837459994812426>
<:Agile:1054837638730879106> <:FireSword:1054837553951416431> <:Meditation:1054837527204352010> <:IronWill:1054837555482341487>

**• Поздняя игра**
<:Meditation:1054837527204352010> <:RedLightning:1054837517523882115> <:Agile:1054837638730879106> <:FireSword:1054837553951416431> <:Supersonic:1054837538793197628>
<:FlowingBlade:1054837613074321561> <:Flamewave:1054837524343824444> <:Blizzard:1054837537312608287> <:BurningSword:1054837580388126721> <:Fulgurous:1054837528714293288>

<:noah:1060758788237443132> **Духи**
<:kart:1060759190672515092> <:luga:1060758784106057880> <:mum:1060758787092402237> <:todd:1060758778221436989> <:zappy:1060758779488112701> <:radon:1060758791207002131> предпочтительнее использовать любой из них, но наиболее заметными являются <:todd:1060758778221436989> <:zappy:1060758779488112701> <:mum:1060758787092402237>.

<:HI:1319143179454517358> **Знакомые**
После 8* фамильяров можно использовать в фермерских постройках. Тест с и без, так как на сцене все может отличаться.
<:PE:1319159006841012306> <:MUS:1319159228266578000> — предпочтительные фамильяры для фермерства, используйте того элементарного фамильяра, который сильнее.

<:guide:1055587557976580106> **Советы**
В общем, вы должны убедиться, что можете стрелять в монстров с одного выстрела с помощью <:Fulgurous:1054837528714293288>, то же самое касается <:Supersonic:1054837538793197628>.

Если у вас заканчивается мана во время фарма с использованием fulgurous, вы можете использовать <:LifeMana:1054837659052285972> или уровень маны, пассивную способность первой страницы на Луне.
**Информация по навыкам**
<:Fulgurous:1054837528714293288>, <:Supersonic:1054837538793197628>, <:Agile:1054837638730879106>, <:Meditation:1054837527204352010> — потрясающие навыки для поэтапного фарма. Медитация очень хорошо сочетается с активными усилениями, например <:FireSword:1054837553951416431> <:FlowingBlade:1054837613074321561> <:Agile:1054837638730879106> , а также с <:Blizzard:1054837537312608287> лучшим доступным умением очистки волн по площади.
Моя собственная сборка с семьей; Я делаю это для поздней игры.
https://cdn.jsdelivr.net/gh/Nihronick/blackrose@main/assets/media/guides/stage/stage_farm_builds/Fam_for_Stage_Farm.mp4
