INSERT INTO guides (key, category_key, title, text, photo, video)
VALUES (
  'stage_stage_farm_info',
  'stage',
  'Stage Farm Info',
  'Основная информация о стадиях и зонах.

## База по стадиям
* Стадии сгруппированы по зонам: в каждой зоне 20 стадий, а после Black Forest добавляется Soul Color.
* В каждой стадии 10 волн, но число монстров в волне отличается от стадии к стадии.
* Время прохождения стадии (от черного экрана до черного экрана, либо от Spirit Beam до Spirit Beam) обычно называют "Clear Time".
* Цвета души: Green, Blue, Red. Подробнее: [[stage_stage_farm_info]]

### Монстры на волну (MPW)
* MPW можно посмотреть в игре через "Details" на экране "Select Region" или в <#1092343850019868682> > Master Document. **Важно: в "Details" MPW отображается только после прохождения Stage 160.**
* Ключевые стадии - это 4mpw и 18mpw (**после Stage 160**):
> **4mpw** -> Эти стадии хороши для фарма **EXP** и **GOLD**. Из-за меньшего количества мобов clear time ниже, поэтому вы можете фармить более высокие стадии и получать больше **EXP** и **GOLD**.
>
> **18mpw** -> Эти стадии хороши для фарма **Cubes**, **Souls**, **Equipment** и **Diamonds**. Да, обычно приходится опускаться на более низкие стадии ради комфортного clear time (примерно 36-42 секунды), но за счет большего числа убийств вы получаете больше этих ресурсов.

**Фарм**
Новым игрокам лучше фармить самую высокую стадию, которую вы закрываете ваншотом через fulgurous. Сборки ранней и средней игры из связанного форума <#1189111915750899732> подходят для стадий с меньшим MPW. Если вы на Ether или ниже и у вас еще нет максимального Deathstrike % и уровня 4000 DSD, чаще всего выгоднее фармить 4mpw ради золота. После этого можно тратить 2 часа на 4mpw под EXP/GOLD-бафы, а остальное время - на 18mpw.

### Онлайн и оффлайн
* Онлайн-фарм лучше оффлайн-фарма.
1. У оффлайна ограничение по времени (10 часов): если забыли зайти и забрать награды, прогресс останавливается.
2. Нет алмазов из ежедневных заданий.
3. Нет дропа экипировки с оффлайн-фарма.
4. Скорость добычи cubes и souls в оффлайне заметно ниже, чем онлайн (это видно в Stage Calculator).

* Но у оффлайн-фарма есть и плюсы (особенно в самом начале игры):
> * До Stage 160 вы не выбираете между 4mpw и 18mpw, поэтому вариантов фарма меньше.
> * Оффлайн дает больше dices, что помогает довести Slayer Promotion и Companion Promotion abilities до mythic.

**Дроп экипировки**
Частоту дропа можно посмотреть, нажав на карту в верхней части экрана. Для каждой стадии отображаются номер стадии, MPW (monsters per wave), выпадающий Weapon/Accessory и его drop rate.

### Схема использования свитков

Старт - <:adamant:1054852905020170390>
foc/shelter -> (в будни с ивентовым бафом на кубы) свиток кубов + rift -> свиток экипировки 2ч 18mpw -> hot time при наличии -> свиток exp + tc -> (в выходные с ивентовым бафом на золото) свиток золота + DV при наличии + 22ч 4mpw

<:ether:1060039749336830002> - <:Cyclos:1209706860727242823>
Ивентовый баф здесь остается тем же: кубы в будни, золото в выходные.
Будни
foc/shelter -> свиток exp + tc -> свиток золота + DV при наличии + 2ч 4mpw -> свиток кубов + rift -> свиток экипировки -> 22ч фарма 18mpw

Хот-тайм
foc/shelter -> hot time -> свиток exp + tc -> свиток золота + DV -> 2ч 4mpw -> свиток кубов + rift -> свиток экипировки -> 22ч фарма 18mpw

Хот-тайм во время ивента
foc/shelter -> свиток кубов + rift -> hot time -> свиток exp + tc -> свиток золота + DV -> cm (опционально) -> свиток экипировки -> 22ч фарма 18mpw

<:AncientCanine:1257278191832399872> +
Ивентовый баф на ваше усмотрение
Будни
foc/shelter -> свиток кубов + rift -> свиток exp + tc -> свиток золота + DV при наличии -> свиток экипировки + маунт -> 24ч фарма 18mpw

Хот-тайм
foc/shelter -> свиток кубов + rift -> hot time -> свиток золота + DV при наличии -> свиток exp + tc -> cm при ивенте в выходные -> свиток экипировки + маунт -> 24ч фарма 18mpw
